const e={"ko-first-u01.title":"Tiere","ko-first-u01.tip":"Schauen Sie das Bild an, hören Sie zu und sprechen Sie das koreanische Wort gemeinsam. Es ist nicht schlimm, wenn Ihr Kind noch nicht lesen kann.","ko-first-u01.w.0":"Katze","ko-first-u01.w.1":"Hündchen","ko-first-u01.w.2":"Fisch","ko-first-u01.w.3":"Vogel","ko-first-u01.w.4":"Kuh","ko-first-u01.w.5":"Schwein","ko-first-u02.title":"Etwas zum Essen","ko-first-u02.tip":"Schauen Sie das Bild an, hören Sie zu und sprechen Sie das koreanische Wort gemeinsam. Es ist nicht schlimm, wenn Ihr Kind noch nicht lesen kann.","ko-first-u02.w.0":"Apfel","ko-first-u02.w.1":"Banane","ko-first-u02.w.2":"Milch","ko-first-u02.w.3":"Brot","ko-first-u02.w.4":"Ei","ko-first-u02.w.5":"Reis","ko-first-u03.title":"Spielsachen","ko-first-u03.tip":"Schauen Sie das Bild an, hören Sie zu und sprechen Sie das koreanische Wort gemeinsam. Es ist nicht schlimm, wenn Ihr Kind noch nicht lesen kann.","ko-first-u03.w.0":"Ball","ko-first-u03.w.1":"Auto","ko-first-u03.w.2":"Teddybär","ko-first-u03.w.3":"Drachen","ko-first-u03.w.4":"Zug","ko-first-u03.w.5":"Boot","ko-first-u04.title":"Der Körper","ko-first-u04.tip":"Schauen Sie das Bild an, hören Sie zu und sprechen Sie das koreanische Wort gemeinsam. Es ist nicht schlimm, wenn Ihr Kind noch nicht lesen kann.","ko-first-u04.w.0":"Auge","ko-first-u04.w.1":"Ohr","ko-first-u04.w.2":"Nase","ko-first-u04.w.3":"Mund","ko-first-u04.w.4":"Hand","ko-first-u04.w.5":"Fuß","ko-first-u05.title":"Farben","ko-first-u05.tip":"Schauen Sie das Bild an, hören Sie zu und sprechen Sie das koreanische Wort gemeinsam. Es ist nicht schlimm, wenn Ihr Kind noch nicht lesen kann.","ko-first-u05.w.0":"rot","ko-first-u05.w.1":"blau","ko-first-u05.w.2":"gelb","ko-first-u05.w.3":"grün","ko-first-u05.w.4":"schwarz","ko-first-u05.w.5":"weiß","ko-first-u06.title":"Familie","ko-first-u06.tip":"Schauen Sie das Bild an, hören Sie zu und sprechen Sie das koreanische Wort gemeinsam. Es ist nicht schlimm, wenn Ihr Kind noch nicht lesen kann.","ko-first-u06.w.0":"Mama","ko-first-u06.w.1":"Papa","ko-first-u06.w.2":"Baby","ko-first-u06.w.3":"Oma","ko-first-u06.w.4":"Opa","ko-first-u06.w.5":"Kind","ko-first-u07.title":"Zu Hause","ko-first-u07.tip":"Schauen Sie das Bild an, hören Sie zu und sprechen Sie das koreanische Wort gemeinsam. Es ist nicht schlimm, wenn Ihr Kind noch nicht lesen kann.","ko-first-u07.w.0":"Haus","ko-first-u07.w.1":"Bett","ko-first-u07.w.2":"Stuhl","ko-first-u07.w.3":"Tür","ko-first-u07.w.4":"Buch","ko-first-u07.w.5":"Tasse","ko-first-u08.title":"Draußen","ko-first-u08.tip":"Schauen Sie das Bild an, hören Sie zu und sprechen Sie das koreanische Wort gemeinsam. Es ist nicht schlimm, wenn Ihr Kind noch nicht lesen kann.","ko-first-u08.w.0":"Sonne","ko-first-u08.w.1":"Mond","ko-first-u08.w.2":"Stern","ko-first-u08.w.3":"Baum","ko-first-u08.w.4":"Blume","ko-first-u08.w.5":"Regen"},n={"ko-kinder-u01.title":"Vokale ㅏ ㅓ ㅗ ㅜ ㅣ","ko-kinder-u01.tip":"Koreanische Buchstaben setzen sich zu Blöcken zusammen. ㅇ am Anfang ist stumm, darum klingt 아 einfach wie „a“. Sag 아, 어, 오, 우, 이 mit großen Mundbewegungen!","ko-kinder-u01.w.0":"Baby","ko-kinder-u01.w.1":"Eis","ko-kinder-u01.w.2":"Mama","ko-kinder-u01.w.3":"Ente","ko-kinder-u01.w.4":"Gurke","ko-kinder-u01.w.5":"Milch","ko-kinder-u01.w.6":"Regenschirm","ko-kinder-u01.w.7":"Zahn","ko-kinder-u01.s.0":"Das Baby schläft.","ko-kinder-u01.s.1":"Eine Ente kommt.","ko-kinder-u01.s.2":"Milch, bitte.","ko-kinder-u02.title":"Buchstaben ㄱ ㄴ ㄷ","ko-kinder-u02.tip":"Ein Block ist ein Konsonant plus ein Vokal: ㄱ + ㅏ = 가. Tippe auf jede Karte, um den Namen des Buchstabens zu hören, und lest dann den Block zusammen.","ko-kinder-u02.w.0":"Tasche","ko-kinder-u02.w.1":"Fleisch","ko-kinder-u02.w.2":"Schuhe","ko-kinder-u02.w.3":"Schmetterling","ko-kinder-u02.w.4":"Baum","ko-kinder-u02.w.5":"Lied","ko-kinder-u02.w.6":"Eichhörnchen","ko-kinder-u02.w.7":"Eichel","ko-kinder-u02.s.0":"Der Schmetterling fliegt.","ko-kinder-u02.s.1":"Die Tasche ist groß.","ko-kinder-u02.s.2":"Das Eichhörnchen frisst.","ko-kinder-u03.title":"Buchstaben ㄹ ㅁ ㅂ","ko-kinder-u03.tip":"ㄹ klingt wie etwas zwischen „r“ und „l“. ㅁ sieht aus wie ein geschlossener Mund — und du schließt die Lippen, um ihn zu sagen!","ko-kinder-u03.w.0":"Ramen","ko-kinder-u03.w.1":"Zitrone","ko-kinder-u03.w.2":"Pferd","ko-kinder-u03.w.3":"Hut","ko-kinder-u03.w.4":"Regenbogen","ko-kinder-u03.w.5":"Banane","ko-kinder-u03.w.6":"Bus","ko-kinder-u03.w.7":"Regen","ko-kinder-u03.s.0":"Der Hut ist hübsch.","ko-kinder-u03.s.1":"Der Bus kommt.","ko-kinder-u03.s.2":"Es regnet.","ko-kinder-u04.title":"Buchstaben ㅅ ㅇ ㅈ","ko-kinder-u04.tip":"ㅇ ist am Anfang eines Blocks stumm (아, 오), aber unten klingt es wie „ng“ (방). ㅅ sieht aus wie ein kleines Zelt: 사, 소.","ko-kinder-u04.w.0":"Löwe","ko-kinder-u04.w.1":"Apfel","ko-kinder-u04.w.2":"Kuh","ko-kinder-u04.w.3":"Wassermelone","ko-kinder-u04.w.4":"Uhr","ko-kinder-u04.w.5":"Auto","ko-kinder-u04.w.6":"Saft","ko-kinder-u04.w.7":"Erde (Planet)","ko-kinder-u04.s.0":"Der Löwe ist groß.","ko-kinder-u04.s.1":"Saft, bitte.","ko-kinder-u04.s.2":"Die Wassermelone ist lecker.","ko-kinder-u05.title":"Buchstaben ㅊ ㅋ ㅌ","ko-kinder-u05.tip":"ㅊ, ㅋ, ㅌ sind „Puste-Buchstaben“: ㅋ ist ㄱ mit einem Extrastrich und einem extra Hauch Luft. Halte die Hand vor den Mund und fühl es!","ko-kinder-u05.w.0":"Rock","ko-kinder-u05.w.1":"Käse","ko-kinder-u05.w.2":"Nase","ko-kinder-u05.w.3":"Elefant","ko-kinder-u05.w.4":"Keks","ko-kinder-u05.w.5":"Hase","ko-kinder-u05.w.6":"Tomate","ko-kinder-u05.w.7":"Lastwagen","ko-kinder-u05.s.0":"Der Hase hüpft.","ko-kinder-u05.s.1":"Der Rüssel des Elefanten ist lang.","ko-kinder-u05.s.2":"Einen Keks, bitte.","ko-kinder-u06.title":"Buchstaben ㅍ ㅎ","ko-kinder-u06.tip":"ㅎ klingt wie „h“ — 하, 호, 후, wie ein kleines Lachen. Jetzt kennst du alle 14 Grundkonsonanten!","ko-kinder-u06.w.0":"Weintrauben","ko-kinder-u06.w.1":"Pizza","ko-kinder-u06.w.2":"Welle","ko-kinder-u06.w.3":"Pinguin","ko-kinder-u06.w.4":"Nilpferd","ko-kinder-u06.w.5":"Sonne","ko-kinder-u06.w.6":"Tiger","ko-kinder-u06.w.7":"Taschentuch","ko-kinder-u06.s.0":"Der Pinguin läuft.","ko-kinder-u06.s.1":"Der Tiger schläft.","ko-kinder-u06.s.2":"Die Weintrauben sind lecker.","ko-kinder-u07.title":"Vokale ㅑ ㅕ ㅛ ㅠ ㅐ ㅔ","ko-kinder-u07.tip":"Ein Extrastrich fügt ein „j“ hinzu: ㅏ (a) → ㅑ (ja), ㅗ (o) → ㅛ (jo). ㅐ und ㅔ klingen heute fast gleich — sogar Koreaner verwechseln sie!","ko-kinder-u07.w.0":"Baseball","ko-kinder-u07.w.1":"Fuchs","ko-kinder-u07.w.2":"Kochen","ko-kinder-u07.w.3":"Gespenst","ko-kinder-u07.w.4":"Raupe","ko-kinder-u07.w.5":"Hund","ko-kinder-u07.w.6":"Birne","ko-kinder-u07.w.7":"Krabbe","ko-kinder-u07.s.0":"Der Fuchs lächelt.","ko-kinder-u07.s.1":"Die Krabbe läuft.","ko-kinder-u07.s.2":"Ich koche.","ko-kinder-u08.title":"Untere Buchstaben (Batchim)","ko-kinder-u08.tip":"Ein Konsonant kann unten in einem Block sitzen: ㄱ + ㅗ + ㅁ = 곰. Dieser untere Buchstabe heißt Batchim (받침). Jetzt kannst du fast jedes koreanische Wort lesen!","ko-kinder-u08.w.0":"Bär","ko-kinder-u08.w.1":"Ball","ko-kinder-u08.w.2":"Schnee","ko-kinder-u08.w.3":"Berg","ko-kinder-u08.w.4":"Brot","ko-kinder-u08.w.5":"Stern","ko-kinder-u08.w.6":"Mond","ko-kinder-u08.w.7":"Wasser","ko-kinder-u08.s.0":"Der Bär schläft.","ko-kinder-u08.s.1":"Es schneit.","ko-kinder-u08.s.2":"Wasser, bitte."},i={"ko-g12-u01.title":"Begrüßen","ko-g12-u01.tip":"Verbeuge dich ein bisschen, wenn du 안녕하세요 sagst — so grüßen sich Koreaner. Bei guten Freunden reicht einfach 안녕!","ko-g12-u01.w.0":"hallo","ko-g12-u01.w.1":"tschüss (zu jemandem, der geht)","ko-g12-u01.w.2":"danke","ko-g12-u01.w.3":"Entschuldigung","ko-g12-u01.w.4":"ja","ko-g12-u01.w.5":"nein","ko-g12-u01.w.6":"Freund","ko-g12-u01.w.7":"Lehrer","ko-g12-u01.w.8":"gute Nacht","ko-g12-u01.s.0":"Guten Tag, Frau Lehrerin.","ko-g12-u01.s.1":"Ja, danke.","ko-g12-u01.s.2":"Nein, schon gut.","ko-g12-u01.s.3":"Es tut mir wirklich leid.","ko-g12-u01.s.4":"Hallo, mein Freund!","ko-g12-u01.s.5":"Gute Nacht, Mama.","ko-g12-u02.title":"Zahlen 1–10","ko-g12-u02.tip":"Im Koreanischen gibt es zwei Zahlenreihen. Mit 하나, 둘, 셋 zählt man Dinge und sagt sein Alter. Zähl damit deine Finger!","ko-g12-u02.w.0":"eins","ko-g12-u02.w.1":"zwei","ko-g12-u02.w.2":"drei","ko-g12-u02.w.3":"vier","ko-g12-u02.w.4":"fünf","ko-g12-u02.w.5":"sechs","ko-g12-u02.w.6":"sieben","ko-g12-u02.w.7":"acht","ko-g12-u02.w.8":"neun","ko-g12-u02.w.9":"zehn","ko-g12-u02.s.0":"Eins, zwei, drei!","ko-g12-u02.s.1":"Vier, fünf, sechs.","ko-g12-u02.s.2":"Sieben, acht, neun, zehn.","ko-g12-u02.s.3":"Ich bin fünf Jahre alt.","ko-g12-u02.s.4":"Ich habe zehn Finger.","ko-g12-u02.s.5":"Noch einen, bitte.","ko-g12-u03.title":"Farben","ko-g12-u03.tip":"Jedes Farbwort endet auf 색 (Farbe). Zeig auf Dinge um dich herum und sag ihre Farbe: 빨간색!","ko-g12-u03.w.0":"rot","ko-g12-u03.w.1":"blau","ko-g12-u03.w.2":"gelb","ko-g12-u03.w.3":"grün","ko-g12-u03.w.4":"lila","ko-g12-u03.w.5":"orange (Farbe)","ko-g12-u03.w.6":"rosa","ko-g12-u03.w.7":"schwarz","ko-g12-u03.w.8":"weiß","ko-g12-u03.s.0":"Äpfel sind rot.","ko-g12-u03.s.1":"Der Himmel ist blau.","ko-g12-u03.s.2":"Bananen sind gelb.","ko-g12-u03.s.3":"Blätter sind grün.","ko-g12-u03.s.4":"Weintrauben sind lila.","ko-g12-u03.s.5":"Ich mag Rosa.","ko-g12-u04.title":"Familie","ko-g12-u04.tip":"Für Familie und Zuhause sagen Koreaner 우리 (unser) statt „mein“: 우리 엄마, 우리 집. Das klingt warm und freundlich.","ko-g12-u04.w.0":"Familie","ko-g12-u04.w.1":"Mama","ko-g12-u04.w.2":"Papa","ko-g12-u04.w.3":"Oma","ko-g12-u04.w.4":"Opa","ko-g12-u04.w.5":"jüngeres Geschwisterkind","ko-g12-u04.w.6":"Baby","ko-g12-u04.w.7":"Hündchen","ko-g12-u04.s.0":"Das ist meine Familie.","ko-g12-u04.s.1":"Mama, ich hab dich lieb.","ko-g12-u04.s.2":"Papa ist groß.","ko-g12-u04.s.3":"Oma lächelt.","ko-g12-u04.s.4":"Mein kleiner Bruder weint.","ko-g12-u04.s.5":"Das Hündchen gehört auch zur Familie.","ko-g12-u05.title":"Tiere","ko-g12-u05.tip":"Tierlaute auf Koreanisch sind lustig: Die Katze macht 야옹, der Hund macht 멍멍, der Frosch macht 개굴개굴. Probier es aus!","ko-g12-u05.w.0":"Katze","ko-g12-u05.w.1":"Affe","ko-g12-u05.w.2":"Giraffe","ko-g12-u05.w.3":"Maus","ko-g12-u05.w.4":"Schlange","ko-g12-u05.w.5":"Huhn","ko-g12-u05.w.6":"Schaf","ko-g12-u05.w.7":"Schildkröte","ko-g12-u05.w.8":"Frosch","ko-g12-u05.s.0":"Die Katze macht miau.","ko-g12-u05.s.1":"Giraffen haben einen langen Hals.","ko-g12-u05.s.2":"Der Affe isst eine Banane.","ko-g12-u05.s.3":"Schildkröten sind langsam.","ko-g12-u05.s.4":"Der Frosch hüpft.","ko-g12-u05.s.5":"Das Schaf frisst Gras.","ko-g12-u06.title":"Obst","ko-g12-u06.tip":"배 heißt Birne — aber auch Schiff und Bauch! Das Bild verrät dir, was gemeint ist.","ko-g12-u06.w.0":"Apfel","ko-g12-u06.w.1":"Banane","ko-g12-u06.w.2":"Erdbeere","ko-g12-u06.w.3":"Weintrauben","ko-g12-u06.w.4":"Wassermelone","ko-g12-u06.w.5":"Mandarine","ko-g12-u06.w.6":"Pfirsich","ko-g12-u06.w.7":"Birne","ko-g12-u06.w.8":"Kiwi","ko-g12-u06.s.0":"Die Erdbeere ist rot.","ko-g12-u06.s.1":"Die Mandarine ist süß.","ko-g12-u06.s.2":"Ich mag Pfirsiche.","ko-g12-u06.s.3":"Die Wassermelone ist richtig groß.","ko-g12-u06.s.4":"Weintrauben, bitte.","ko-g12-u06.s.5":"Kiwis sind grün.","ko-g12-u07.title":"Essen","ko-g12-u07.tip":"Vor dem Essen sagen Koreaner 잘 먹겠습니다 (ich werde gut essen) und danach 잘 먹었습니다. Probier es bei der nächsten Mahlzeit!","ko-g12-u07.w.0":"Reis","ko-g12-u07.w.1":"Kimchi","ko-g12-u07.w.2":"Suppe","ko-g12-u07.w.3":"Gimbap (Reisrolle)","ko-g12-u07.w.4":"Reiskuchen","ko-g12-u07.w.5":"Teigtasche","ko-g12-u07.w.6":"Ei","ko-g12-u07.w.7":"Fisch (zum Essen)","ko-g12-u07.w.8":"Löffel","ko-g12-u07.w.9":"Stäbchen","ko-g12-u07.s.0":"Ich esse Reis.","ko-g12-u07.s.1":"Das Kimchi ist scharf.","ko-g12-u07.s.2":"Die Teigtaschen sind lecker.","ko-g12-u07.s.3":"Die Suppe ist heiß.","ko-g12-u07.s.4":"Ich esse mit Stäbchen.","ko-g12-u07.s.5":"Gimbap, bitte.","ko-g12-u07.s.6":"Ich habe Hunger.","ko-g12-u08.title":"Der Körper","ko-g12-u08.tip":"Spiel „Simon sagt“ auf Koreanisch: 코! 귀! 머리! Berühre jeden Körperteil, wenn du ihn hörst.","ko-g12-u08.w.0":"Kopf","ko-g12-u08.w.1":"Auge","ko-g12-u08.w.2":"Nase","ko-g12-u08.w.3":"Mund","ko-g12-u08.w.4":"Ohr","ko-g12-u08.w.5":"Hand","ko-g12-u08.w.6":"Fuß","ko-g12-u08.w.7":"Bein","ko-g12-u08.w.8":"Arm","ko-g12-u08.s.0":"Ich habe zwei Augen.","ko-g12-u08.s.1":"Fass dir an die Nase.","ko-g12-u08.s.2":"Ich wasche mir die Hände.","ko-g12-u08.s.3":"Mach den Mund weit auf.","ko-g12-u08.s.4":"Mir tut der Kopf weh.","ko-g12-u08.s.5":"Meine Beine sind lang.","ko-g12-u09.title":"Schule","ko-g12-u09.tip":"In Korea nennen Schüler ihre Lehrerin oder ihren Lehrer 선생님 — nie nur beim Namen. 님 ist eine höfliche Endung, die Respekt zeigt.","ko-g12-u09.w.0":"Schule","ko-g12-u09.w.1":"Klassenzimmer","ko-g12-u09.w.2":"Bleistift","ko-g12-u09.w.3":"Radiergummi","ko-g12-u09.w.4":"Heft","ko-g12-u09.w.5":"Schere","ko-g12-u09.w.6":"Schreibtisch","ko-g12-u09.w.7":"Tafel","ko-g12-u09.w.8":"Hausaufgaben","ko-g12-u09.s.0":"Ich gehe zur Schule.","ko-g12-u09.s.1":"Ich habe einen Bleistift.","ko-g12-u09.s.2":"Leih mir bitte einen Radiergummi.","ko-g12-u09.s.3":"Ich schreibe in mein Heft.","ko-g12-u09.s.4":"Ich habe viele Hausaufgaben.","ko-g12-u09.s.5":"Frau Lehrerin, ich habe eine Frage!","ko-g12-u10.title":"Zu Hause","ko-g12-u10.tip":"Koreaner ziehen an der Tür die Schuhe aus, bevor sie hineingehen. Der Boden ist oft warm (Ondol-Heizung) — gemütlich!","ko-g12-u10.w.0":"Haus","ko-g12-u10.w.1":"Zimmer","ko-g12-u10.w.2":"Küche","ko-g12-u10.w.3":"Badezimmer","ko-g12-u10.w.4":"Lampe","ko-g12-u10.w.5":"Tür","ko-g12-u10.w.6":"Sofa","ko-g12-u10.w.7":"Kühlschrank","ko-g12-u10.w.8":"Fernseher","ko-g12-u10.s.0":"Unser Haus ist klein.","ko-g12-u10.s.1":"Das ist mein Zimmer.","ko-g12-u10.s.2":"Mama ist in der Küche.","ko-g12-u10.s.3":"Ich mache das Licht an.","ko-g12-u10.s.4":"Ich setze mich aufs Sofa.","ko-g12-u10.s.5":"Wo ist das Badezimmer?","ko-g12-u11.title":"Kleidung","ko-g12-u11.tip":"Im Koreanischen gibt es verschiedene Verben fürs „Anziehen“: 입어요 für Kleidung, 신어요 für Socken und Schuhe, 써요 für Mützen und Hüte. Lustig, oder?","ko-g12-u11.w.0":"Kleidung","ko-g12-u11.w.1":"T-Shirt","ko-g12-u11.w.2":"Hose","ko-g12-u11.w.3":"Rock","ko-g12-u11.w.4":"Socken","ko-g12-u11.w.5":"Schuhe","ko-g12-u11.w.6":"Hut","ko-g12-u11.w.7":"Handschuhe","ko-g12-u11.w.8":"Schlafanzug","ko-g12-u11.s.0":"Ich ziehe mich an.","ko-g12-u11.s.1":"Ich ziehe meine Socken an.","ko-g12-u11.s.2":"Ich setze meinen Hut auf.","ko-g12-u11.s.3":"Meine Schuhe sind klein.","ko-g12-u11.s.4":"Die Handschuhe sind warm.","ko-g12-u11.s.5":"Der Schlafanzug ist hübsch.","ko-g12-u12.title":"Wetter","ko-g12-u12.tip":"Regen und Schnee „kommen“ auf Koreanisch: 비가 와요, 눈이 와요. Korea hat vier deutliche Jahreszeiten — welche magst du?","ko-g12-u12.w.0":"Wetter","ko-g12-u12.w.1":"Sonne","ko-g12-u12.w.2":"Regen","ko-g12-u12.w.3":"Schnee","ko-g12-u12.w.4":"Wind","ko-g12-u12.w.5":"Wolke","ko-g12-u12.w.6":"Frühling","ko-g12-u12.w.7":"Sommer","ko-g12-u12.w.8":"Herbst","ko-g12-u12.w.9":"Winter","ko-g12-u12.s.0":"Das Wetter ist schön.","ko-g12-u12.s.1":"Es regnet.","ko-g12-u12.s.2":"Es schneit.","ko-g12-u12.s.3":"Der Wind weht.","ko-g12-u12.s.4":"Der Sommer ist heiß.","ko-g12-u12.s.5":"Der Winter ist kalt.","ko-g12-u12.s.6":"Im Frühling blühen die Blumen.","ko-g12-u13.title":"Tage und Zeit","ko-g12-u13.tip":"Alle Wochentage enden auf 요일 (Wochentag). 토요일 und 일요일 sind das Wochenende — juhu!","ko-g12-u13.w.0":"Montag","ko-g12-u13.w.1":"Freitag","ko-g12-u13.w.2":"Samstag","ko-g12-u13.w.3":"Sonntag","ko-g12-u13.w.4":"heute","ko-g12-u13.w.5":"morgen","ko-g12-u13.w.6":"gestern","ko-g12-u13.w.7":"Morgen (Tageszeit)","ko-g12-u13.w.8":"Nacht","ko-g12-u13.s.0":"Heute ist Montag.","ko-g12-u13.s.1":"Morgen ist Samstag.","ko-g12-u13.s.2":"Am Sonntag ruhe ich mich aus.","ko-g12-u13.s.3":"Am Morgen stehe ich auf.","ko-g12-u13.s.4":"In der Nacht schlafe ich.","ko-g12-u13.s.5":"Ich mag Freitage.","ko-g12-u14.title":"Unterwegs","ko-g12-u14.tip":"Auf Koreanisch „fährt“ man mit jedem Fahrzeug mit demselben Verb: 버스를 타요, 자전거를 타요, 비행기를 타요.","ko-g12-u14.w.0":"Bus","ko-g12-u14.w.1":"U-Bahn","ko-g12-u14.w.2":"Taxi","ko-g12-u14.w.3":"Zug","ko-g12-u14.w.4":"Flugzeug","ko-g12-u14.w.5":"Fahrrad","ko-g12-u14.w.6":"Schiff","ko-g12-u14.w.7":"Auto","ko-g12-u14.w.8":"Straße","ko-g12-u14.s.0":"Ich fahre mit dem Bus.","ko-g12-u14.s.1":"Die U-Bahn ist schnell.","ko-g12-u14.s.2":"Ich fahre Fahrrad.","ko-g12-u14.s.3":"Das Flugzeug fliegt.","ko-g12-u14.s.4":"Der Zug ist lang.","ko-g12-u14.s.5":"Auf der Straße ist Stau.","ko-g12-u15.title":"Spielzeug und Spielen","ko-g12-u15.tip":"Beim Verstecken zählen koreanische Kinder und rufen 꼭꼭 숨어라, 머리카락 보일라 — „Versteck dich gut, ich sehe deine Haare!“","ko-g12-u15.w.0":"Spielzeug","ko-g12-u15.w.1":"Puppe","ko-g12-u15.w.2":"Bauklötze","ko-g12-u15.w.3":"Ball","ko-g12-u15.w.4":"Tretroller","ko-g12-u15.w.5":"Puzzle","ko-g12-u15.w.6":"Luftballon","ko-g12-u15.w.7":"Spiel","ko-g12-u15.w.8":"Verstecken","ko-g12-u15.s.0":"Lass uns zusammen spielen!","ko-g12-u15.s.1":"Ich werfe den Ball.","ko-g12-u15.s.2":"Ich fahre mit meinem Tretroller.","ko-g12-u15.s.3":"Ich baue ein Haus aus Bauklötzen.","ko-g12-u15.s.4":"Der Luftballon fliegt davon.","ko-g12-u15.s.5":"Lass uns Verstecken spielen.","ko-g12-u16.title":"Natur","ko-g12-u16.tip":"Große Teile Koreas sind von Bergen bedeckt, darum ist Wandern (등산) ein beliebter Wochenendausflug für Familien.","ko-g12-u16.w.0":"Berg","ko-g12-u16.w.1":"Meer","ko-g12-u16.w.2":"Fluss","ko-g12-u16.w.3":"Himmel","ko-g12-u16.w.4":"Blume","ko-g12-u16.w.5":"Baum","ko-g12-u16.w.6":"Gras","ko-g12-u16.w.7":"Sand","ko-g12-u16.w.8":"Stern","ko-g12-u16.s.0":"Der Berg ist hoch.","ko-g12-u16.s.1":"Das Meer ist weit.","ko-g12-u16.s.2":"Der Himmel ist klar.","ko-g12-u16.s.3":"Die Blume ist hübsch.","ko-g12-u16.s.4":"Der Baum ist groß.","ko-g12-u16.s.5":"Am Nachthimmel sind viele Sterne.","ko-g12-u17.title":"Gefühle","ko-g12-u17.tip":"Auf Koreanisch funktionieren Gefühlswörter wie Verben: 기뻐요 heißt schon „(ich) bin froh“. Wenn jemand traurig aussieht, frag 괜찮아요?","ko-g12-u17.w.0":"froh","ko-g12-u17.w.1":"traurig","ko-g12-u17.w.2":"wütend","ko-g12-u17.w.3":"ängstlich","ko-g12-u17.w.4":"müde","ko-g12-u17.w.5":"aufgeregt","ko-g12-u17.w.6":"gelangweilt","ko-g12-u17.w.7":"okay","ko-g12-u17.s.0":"Ich bin froh.","ko-g12-u17.s.1":"Mein Freund ist traurig.","ko-g12-u17.s.2":"Ich bin so müde.","ko-g12-u17.s.3":"Heute ist es so aufregend!","ko-g12-u17.s.4":"Geht es dir wirklich gut?","ko-g12-u17.s.5":"Ja, mir geht es gut.","ko-g12-u18.title":"Tätigkeiten","ko-g12-u18.tip":"Wörter, die auf 요 enden, sind höflich. 가요 kann „ich gehe“, „du gehst“ oder „lass uns gehen“ heißen — die Situation verrät es dir!","ko-g12-u18.w.0":"gehen","ko-g12-u18.w.1":"kommen","ko-g12-u18.w.2":"essen","ko-g12-u18.w.3":"trinken","ko-g12-u18.w.4":"schlafen","ko-g12-u18.w.5":"rennen","ko-g12-u18.w.6":"lesen","ko-g12-u18.w.7":"schauen","ko-g12-u18.w.8":"sitzen","ko-g12-u18.s.0":"Ich trinke Wasser.","ko-g12-u18.s.1":"Ich lese ein Buch.","ko-g12-u18.s.2":"Lauf schnell!","ko-g12-u18.s.3":"Setz dich hierher.","ko-g12-u18.s.4":"Schau in den Himmel.","ko-g12-u18.s.5":"Ich gehe nach Hause.","ko-g12-u19.title":"Unsere Nachbarschaft","ko-g12-u19.tip":"Viele Ortswörter enden auf 원, 관 oder 국 — 병원, 도서관, 우체국. Sie kommen von alten chinesischen Schriftzeichen für Gebäude.","ko-g12-u19.w.0":"Nachbarschaft","ko-g12-u19.w.1":"Laden","ko-g12-u19.w.2":"Krankenhaus","ko-g12-u19.w.3":"Park","ko-g12-u19.w.4":"Bücherei","ko-g12-u19.w.5":"Bäckerei","ko-g12-u19.w.6":"Post","ko-g12-u19.w.7":"Spielplatz","ko-g12-u19.w.8":"Polizeiwache","ko-g12-u19.s.0":"Ich gehe in den Park.","ko-g12-u19.s.1":"Die Bäckerei ist nah.","ko-g12-u19.s.2":"In der Bücherei lese ich Bücher.","ko-g12-u19.s.3":"Ich spiele auf dem Spielplatz.","ko-g12-u19.s.4":"Wo ist das Krankenhaus?","ko-g12-u19.s.5":"Der Laden ist groß.","ko-g12-u20.title":"Geburtstagsparty","ko-g12-u20.tip":"Am Geburtstag essen Koreaner 미역국 (Algensuppe) — Mamas essen sie nach der Geburt, darum sagt sie „danke, Mama“.","ko-g12-u20.w.0":"Geburtstag","ko-g12-u20.w.1":"Party","ko-g12-u20.w.2":"Geschenk","ko-g12-u20.w.3":"Kuchen","ko-g12-u20.w.4":"Kerze","ko-g12-u20.w.5":"Lied","ko-g12-u20.w.6":"Karte","ko-g12-u20.w.7":"Algensuppe","ko-g12-u20.w.8":"herzlichen Glückwunsch","ko-g12-u20.s.0":"Alles Gute zum Geburtstag!","ko-g12-u20.s.1":"Danke für das Geschenk.","ko-g12-u20.s.2":"Der Kuchen ist lecker.","ko-g12-u20.s.3":"Ich puste die Kerzen aus.","ko-g12-u20.s.4":"Wir singen ein Lied.","ko-g12-u20.s.5":"Ich esse Algensuppe."},u={"ko-g34-u01.title":"Ich bin …: sich vorstellen","ko-g34-u01.tip":"Schau auf den letzten Block des Wortes: 학생 endet auf ㅇ, also heißt es 학생이에요. 의사 hat keinen unteren Buchstaben, also heißt es 의사예요.","ko-g34-u01.w.0":"Schüler","ko-g34-u01.w.1":"Arzt","ko-g34-u01.w.2":"Koch","ko-g34-u01.w.3":"Sänger","ko-g34-u01.w.4":"Polizist","ko-g34-u01.w.5":"Name","ko-g34-u01.w.6":"Land","ko-g34-u01.w.7":"Mensch","ko-g34-u01.w.8":"Korea","ko-g34-u01.w.9":"ich (höflich)","ko-g34-u01.s.0":"Ich bin Grundschüler.","ko-g34-u01.s.1":"Ich heiße Minjun.","ko-g34-u01.s.2":"Ich bin Amerikaner.","ko-g34-u01.s.3":"Mein Papa ist Arzt.","ko-g34-u01.s.4":"Das ist mein Freund.","ko-g34-u01.s.5":"Ich bin zehn Jahre alt.","ko-g34-u01.s.6":"Die Lehrerin ist Koreanerin.","ko-g34-u01.s.7":"Schön, dich kennenzulernen.","ko-g34-u01.g.title":"Sagen, wer man ist: 이에요 / 예요","ko-g34-u01.g.x.0":"Um „A ist B“ zu sagen, setzt du 이에요 oder 예요 direkt hinter B: 저는 학생이에요 (ich bin Schüler).","ko-g34-u01.g.x.1":"Endet B auf einen unteren Buchstaben (Batchim), nimm 이에요: 학생이에요. Sonst nimm 예요: 의사예요.","ko-g34-u01.g.x.2":"저 heißt „ich“, wenn du höflich sprichst, und 제 heißt „mein“: 제 이름은 지우예요.","ko-g34-u01.g.0":"Ich bin Schüler.","ko-g34-u01.g.1":"Ich bin Arzt.","ko-g34-u01.g.2":"Ich heiße Seoyeon.","ko-g34-u01.g.3":"Ich bin Sänger.","ko-g34-u01.g.4":"Ich bin Koreaner.","ko-g34-u01.g.5":"Ich bin Koch.","ko-g34-u01.g.5.task":"Ersetze 학생 durch 요리사 (Koch).","ko-g34-u01.g.6":"Meine Mama ist Polizistin.","ko-g34-u01.g.6.task":"Ersetze 의사 durch 경찰 (Polizist).","ko-g34-u01.g.7":"Mein Freund ist Kanadier.","ko-g34-u01.g.7.task":"Fang mit 제 친구는 (mein Freund) an.","ko-g34-u01.st.title":"Eine neue Freundin","ko-g34-u01.st.l.0":"Hallo! Ich bin Minjun.","ko-g34-u01.st.l.1":"Hi! Ich bin Emma.","ko-g34-u01.st.l.2":"Emma, aus welchem Land kommst du?","ko-g34-u01.st.l.3":"Ich bin Britin.","ko-g34-u01.st.l.4":"Schön, dich kennenzulernen!","ko-g34-u01.st.l.5":"Ich freue mich auch.","ko-g34-u01.st.q.0":"Woher kommt Emma?","ko-g34-u01.st.q.0.o.0":"영국","ko-g34-u01.st.q.0.o.1":"한국","ko-g34-u01.st.q.0.o.2":"미국","ko-g34-u01.st.q.1":"Wie heißt der Junge?","ko-g34-u01.st.q.1.o.0":"민준","ko-g34-u01.st.q.1.o.1":"엠마","ko-g34-u01.st.q.1.o.2":"지우","ko-g34-u02.title":"Was ist das?","ko-g34-u02.tip":"Zeig beim Sprechen darauf! 이거 ist in deiner Hand, 그거 ist in der Hand deines Freundes, und 저거 ist weit weg von euch beiden.","ko-g34-u02.w.0":"Geldbeutel","ko-g34-u02.w.1":"Brille","ko-g34-u02.w.2":"Schlüssel","ko-g34-u02.w.3":"Handy","ko-g34-u02.w.4":"Foto","ko-g34-u02.w.5":"Ding, Sache","ko-g34-u02.w.6":"das hier","ko-g34-u02.w.7":"das da (bei dir)","ko-g34-u02.w.8":"das dort drüben","ko-g34-u02.w.9":"was","ko-g34-u02.s.0":"Was ist das da (bei dir)?","ko-g34-u02.s.1":"Das ist mein Geldbeutel.","ko-g34-u02.s.2":"Ist das da (bei dir) eine Brille?","ko-g34-u02.s.3":"Ja, das ist eine Brille.","ko-g34-u02.s.4":"Wem gehört das dort drüben?","ko-g34-u02.s.5":"Das ist das Handy der Lehrerin.","ko-g34-u02.s.6":"Diese Brille gehört Opa.","ko-g34-u02.s.7":"Wem gehört der Geldbeutel dort drüben?","ko-g34-u02.g.title":"Dies, das, das dort: 이 / 그 / 저","ko-g34-u02.g.x.0":"이 = dies (nah bei mir), 그 = das (nah bei dir), 저 = das (weit weg von uns beiden).","ko-g34-u02.g.x.1":"Häng 거 an für „Ding“: 이거 (dieses Ding), 그거, 저거. Oder setz ein Nomen dahinter: 이 사진 (dieses Foto), 저 가방 (die Tasche dort).","ko-g34-u02.g.x.2":"Frag mit 뭐예요: 이거 뭐예요? — Was ist das?","ko-g34-u02.g.0":"Was ist das?","ko-g34-u02.g.1":"Das dort drüben ist meine Tasche.","ko-g34-u02.g.2":"Dieses Foto ist schön.","ko-g34-u02.g.3":"Gib mir bitte den Schlüssel.","ko-g34-u02.g.4":"Das da (bei dir) ist mein Handy.","ko-g34-u02.g.5":"Das ist ein Bleistift.","ko-g34-u02.g.5.task":"Ersetze 그거 durch 이거 (das hier).","ko-g34-u02.g.6":"Was ist das dort drüben?","ko-g34-u02.g.6.task":"Frag nach etwas weit Entferntem: nimm 저거.","ko-g34-u02.g.7":"Diese Brille ist schön.","ko-g34-u02.g.7.task":"Ersetze 저 durch 이 (dies).","ko-g34-u03.title":"Ich habe, es gibt","ko-g34-u03.tip":"Ein praktisches Wort: 없어요 allein kann „Ich habe keins“ oder „Es gibt keins“ heißen. 문제 없어요! = Kein Problem!","ko-g34-u03.w.0":"Geld","ko-g34-u03.w.1":"Zeit","ko-g34-u03.w.2":"Geschwister","ko-g34-u03.w.3":"Haustier","ko-g34-u03.w.4":"Problem","ko-g34-u03.w.5":"Verabredung","ko-g34-u03.w.6":"Sitzplatz","ko-g34-u03.w.7":"Bonbon","ko-g34-u03.w.8":"Erkältung","ko-g34-u03.w.9":"Fahrkarte, Eintrittskarte","ko-g34-u03.s.0":"Ich habe ein jüngeres Geschwisterkind.","ko-g34-u03.s.1":"In meinem Geldbeutel ist ein bisschen Geld.","ko-g34-u03.s.2":"Hast du heute Zeit?","ko-g34-u03.s.3":"Zu Hause gibt es eine Katze.","ko-g34-u03.s.4":"Kein Problem.","ko-g34-u03.s.5":"Morgen habe ich eine Verabredung.","ko-g34-u03.s.6":"Ist dieser Platz besetzt?","ko-g34-u03.s.7":"Da ist ein Bonbon.","ko-g34-u03.g.title":"Haben / es gibt: 있어요 · 없어요","ko-g34-u03.g.x.0":"있어요 heißt „es gibt“ oder „ich habe“. 없어요 heißt „es gibt nicht“ oder „ich habe nicht“.","ko-g34-u03.g.x.1":"Setz 이 oder 가 hinter die Sache: 이 nach einem unteren Buchstaben (돈이), 가 ohne unteren Buchstaben (사과가).","ko-g34-u03.g.x.2":"Frag, indem deine Stimme am Ende nach oben geht: 시간 있어요? — Hast du Zeit?","ko-g34-u03.g.0":"Ich habe kein Geld.","ko-g34-u03.g.1":"Da ist ein Apfel.","ko-g34-u03.g.2":"Hast du eine Katze?","ko-g34-u03.g.3":"Ich habe keine Zeit.","ko-g34-u03.g.4":"Ich habe eine Verabredung.","ko-g34-u03.g.5":"Ich habe keine Geschwister.","ko-g34-u03.g.5.task":"Mach daraus „habe nicht“: nimm 없어요.","ko-g34-u03.g.6":"Hier ist eine Karte.","ko-g34-u03.g.6.task":"Ersetze 사탕 durch 표 (Karte). Achte auf 이/가!","ko-g34-u03.g.7":"Hast du ein Haustier?","ko-g34-u03.g.7.task":"Mach daraus eine Frage.","ko-g34-u04.title":"Was mich angeht: 은 / 는","ko-g34-u04.tip":"In Korea rufen Kinder ältere Geschwister nicht beim Namen, sondern mit diesen Titeln. Jungen sagen 형 und 누나, Mädchen sagen 오빠 und 언니.","ko-g34-u04.w.0":"großer Bruder (sagt ein Junge)","ko-g34-u04.w.1":"großer Bruder (sagt ein Mädchen)","ko-g34-u04.w.2":"große Schwester (sagt ein Junge)","ko-g34-u04.w.3":"große Schwester (sagt ein Mädchen)","ko-g34-u04.w.4":"Körpergröße","ko-g34-u04.w.5":"Haare","ko-g34-u04.w.6":"Hobby","ko-g34-u04.w.7":"Sport, Bewegung","ko-g34-u04.w.8":"Musik","ko-g34-u04.w.9":"Charakter","ko-g34-u04.s.0":"Mein großer Bruder ist zwölf.","ko-g34-u04.s.1":"Meine große Schwester ist sehr nett.","ko-g34-u04.s.2":"Ich bin klein.","ko-g34-u04.s.3":"Das Hobby meiner großen Schwester ist Singen.","ko-g34-u04.s.4":"Mein großer Bruder hat kurze Haare.","ko-g34-u04.s.5":"Ich mag Musik.","ko-g34-u04.s.6":"Mein großer Bruder macht jeden Tag Sport.","ko-g34-u04.s.7":"Katzen schlafen viel.","ko-g34-u04.g.title":"Über ein Thema sprechen: 은 / 는","ko-g34-u04.g.x.0":"은/는 zeigt, worüber du sprichst (das Thema): 저는 학생이에요 — Was mich angeht: Ich bin Schüler.","ko-g34-u04.g.x.1":"Nimm 은 nach einem unteren Buchstaben (형은) und 는 ohne unteren Buchstaben (저는, 누나는).","ko-g34-u04.g.x.2":"Es zeigt auch einen Gegensatz: 형은 커요. 저는 작아요. — Mein Bruder ist groß, aber ich bin klein.","ko-g34-u04.g.0":"Ich bin Jiwoo.","ko-g34-u04.g.1":"Mein großer Bruder ist groß.","ko-g34-u04.g.2":"Meine große Schwester mag Musik.","ko-g34-u04.g.3":"Katzen sind süß.","ko-g34-u04.g.4":"Mein Hobby ist Malen.","ko-g34-u04.g.5":"Meine große Schwester hat lange Haare.","ko-g34-u04.g.5.task":"Sprich stattdessen über deine große Schwester (언니).","ko-g34-u04.g.6":"Mein jüngeres Geschwisterkind ist klein.","ko-g34-u04.g.6.task":"Ersetze 형 durch 동생. Achte auf 은/는!","ko-g34-u04.g.7":"Mein großer Bruder ist gut im Sport.","ko-g34-u04.g.7.task":"Sprich über deinen großen Bruder (오빠).","ko-g34-u05.title":"Verben: die Endung 요","ko-g34-u05.tip":"Das 요 am Ende macht einen Satz höflich. Benutze es bei Erwachsenen und Leuten, die du gerade kennenlernst — mit 요 liegst du nie falsch!","ko-g34-u05.w.0":"kaufen","ko-g34-u05.w.1":"treffen","ko-g34-u05.w.2":"lernen (für die Schule)","ko-g34-u05.w.3":"spielen","ko-g34-u05.w.4":"zuhören","ko-g34-u05.w.5":"schreiben","ko-g34-u05.w.6":"arbeiten","ko-g34-u05.w.7":"warten","ko-g34-u05.w.8":"lernen (etwas Neues)","ko-g34-u05.w.9":"gut, schön","ko-g34-u05.s.0":"Ich lerne Koreanisch.","ko-g34-u05.s.1":"Ich treffe meinen Freund im Park.","ko-g34-u05.s.2":"Ich kaufe Brot.","ko-g34-u05.s.3":"Mein kleiner Bruder spielt.","ko-g34-u05.s.4":"Ich höre Musik.","ko-g34-u05.s.5":"Mama wartet.","ko-g34-u05.s.6":"Papa arbeitet.","ko-g34-u05.s.7":"Lass uns zusammen lernen.","ko-g34-u05.g.title":"Höfliche Verbendungen: -아요 / -어요 / 해요","ko-g34-u05.g.x.0":"Koreanische Verben ändern ihre Endung. Nimm 다 weg und häng eine 요-Endung an: 가다 → 가요, 먹다 → 먹어요.","ko-g34-u05.g.x.1":"Ist der letzte Vokal ㅏ oder ㅗ, häng 아요 an: 놀다 → 놀아요, 보다 → 봐요. Bei anderen Vokalen kommt 어요: 먹다 → 먹어요.","ko-g34-u05.g.x.2":"Verben auf 하다 werden zu 해요: 공부하다 → 공부해요.","ko-g34-u05.g.x.3":"Manche Vokale verschmelzen: 기다리다 → 기다려요, 마시다 → 마셔요.","ko-g34-u05.g.0":"Ich treffe meinen Freund.","ko-g34-u05.g.1":"Ich esse Reis.","ko-g34-u05.g.2":"Ich spiele auf dem Spielplatz.","ko-g34-u05.g.3":"Ich lerne Koreanisch.","ko-g34-u05.g.4":"Ich lese ein Buch.","ko-g34-u05.g.5":"Ich kaufe Brot.","ko-g34-u05.g.5.task":"Setz 사다 in die höfliche 요-Form.","ko-g34-u05.g.6":"Mein kleiner Bruder wartet.","ko-g34-u05.g.6.task":"Setz 기다리다 in die höfliche 요-Form.","ko-g34-u05.g.7":"Papa arbeitet in einer Firma.","ko-g34-u05.g.7.task":"Setz 일하다 in die höfliche 요-Form.","ko-g34-u05.st.title":"Was machst du am Samstag?","ko-g34-u05.st.l.0":"Was machst du am Samstag?","ko-g34-u05.st.l.1":"Ich lerne Schwimmen.","ko-g34-u05.st.l.2":"Wow! Ich spiele Fußball.","ko-g34-u05.st.l.3":"Und am Sonntag?","ko-g34-u05.st.l.4":"Ich gehe zu Oma. Wir essen zusammen.","ko-g34-u05.st.l.5":"Schön! Ich ruhe mich zu Hause aus.","ko-g34-u05.st.q.0":"Was lernt Seoyeon am Samstag?","ko-g34-u05.st.q.0.o.0":"수영","ko-g34-u05.st.q.0.o.1":"축구","ko-g34-u05.st.q.0.o.2":"피아노","ko-g34-u05.st.q.1":"Wohin geht Minjun am Sonntag?","ko-g34-u05.st.q.1.o.0":"할머니 집","ko-g34-u05.st.q.1.o.1":"학교","ko-g34-u05.st.q.1.o.2":"공원","ko-g34-u06.title":"Was du isst, siehst und machst: 을 / 를","ko-g34-u06.tip":"Merk dir die Reihenfolge: wer → was → tun. 저는 (ich) 피자를 (Pizza) 먹어요 (esse). Das Tuwort steht immer am Ende!","ko-g34-u06.w.0":"Film","ko-g34-u06.w.1":"Bild, Zeichnung","ko-g34-u06.w.2":"Brief","ko-g34-u06.w.3":"Zeitung","ko-g34-u06.w.4":"Klavier","ko-g34-u06.w.5":"Fußball","ko-g34-u06.w.6":"Schwimmen","ko-g34-u06.w.7":"Putzen","ko-g34-u06.w.8":"Abwaschen","ko-g34-u06.w.9":"Kaffee","ko-g34-u06.s.0":"Ich schaue mit meinem kleinen Bruder einen Film.","ko-g34-u06.s.1":"Ich male ein Bild.","ko-g34-u06.s.2":"Ich schreibe meinem Freund einen Brief.","ko-g34-u06.s.3":"Ich spiele Klavier.","ko-g34-u06.s.4":"Ich spiele Fußball.","ko-g34-u06.s.5":"Papa wäscht ab.","ko-g34-u06.s.6":"Mama trinkt Kaffee.","ko-g34-u06.s.7":"Ich räume mein Zimmer auf.","ko-g34-u06.g.title":"Das, womit man etwas tut: 을 / 를","ko-g34-u06.g.x.0":"을/를 markiert das Objekt — das, was du isst, siehst oder tust: 사과를 먹어요 (ich esse einen Apfel).","ko-g34-u06.g.x.1":"Nimm 을 nach einem unteren Buchstaben (빵을) und 를 ohne unteren Buchstaben (커피를).","ko-g34-u06.g.x.2":"Im Koreanischen steht das Verb ganz am Ende: 저는 영화를 봐요 = ich · einen Film · schaue.","ko-g34-u06.g.0":"Ich schaue einen Film.","ko-g34-u06.g.1":"Ich esse Brot.","ko-g34-u06.g.2":"Ich trinke Kaffee.","ko-g34-u06.g.3":"Ich schreibe einen Brief.","ko-g34-u06.g.4":"Ich lese Zeitung.","ko-g34-u06.g.5":"Ich spiele Klavier.","ko-g34-u06.g.5.task":"Stell das Verb ans Ende.","ko-g34-u06.g.6":"Mein kleiner Bruder malt ein Bild.","ko-g34-u06.g.6.task":"Stell das Verb ans Ende.","ko-g34-u06.g.7":"Mein großer Bruder schwimmt.","ko-g34-u06.g.7.task":"Ersetze 축구 (Fußball) durch 수영 (Schwimmen).","ko-g34-u07.title":"Nicht: 안","ko-g34-u07.tip":"Wenn du kein scharfes Essen magst, ist dieser Satz in Korea nützlich: 안 매운 거 있어요? — Haben Sie etwas, das nicht scharf ist?","ko-g34-u07.w.0":"scharf","ko-g34-u07.w.1":"teuer","ko-g34-u07.w.2":"billig","ko-g34-u07.w.3":"schwierig","ko-g34-u07.w.4":"leicht","ko-g34-u07.w.5":"beschäftigt","ko-g34-u07.w.6":"heiß (Wetter)","ko-g34-u07.w.7":"krank, tut weh","ko-g34-u07.w.8":"lecker","ko-g34-u07.w.9":"lustig","ko-g34-u07.s.0":"Tteokbokki ist ein bisschen scharf.","ko-g34-u07.s.1":"Diese Aufgabe ist nicht leicht.","ko-g34-u07.s.2":"Dieses Buch ist nicht teuer.","ko-g34-u07.s.3":"Papa trinkt Kaffee.","ko-g34-u07.s.4":"Die Hausaufgaben sind nicht schwer.","ko-g34-u07.s.5":"Heute ist es nicht heiß.","ko-g34-u07.s.6":"Es tut nicht mehr weh.","ko-g34-u07.s.7":"Der Film ist richtig lustig.","ko-g34-u07.g.title":"Nicht: 안 + Verb","ko-g34-u07.g.x.0":"Setz 안 direkt vor ein Verb oder Eigenschaftswort, um „nicht“ zu sagen: 매워요 → 안 매워요.","ko-g34-u07.g.x.1":"Bei 해요-Verben steht 안 direkt vor 해요: 공부해요 → 공부 안 해요.","ko-g34-u07.g.x.2":"맛있어요 und 재미있어요 haben ihr eigenes Gegenteil: 맛없어요, 재미없어요.","ko-g34-u07.g.0":"Das Kimchi ist nicht scharf.","ko-g34-u07.g.1":"Ich trinke keinen Kaffee.","ko-g34-u07.g.2":"Heute bin ich nicht beschäftigt.","ko-g34-u07.g.3":"Ich mache keine Hausaufgaben.","ko-g34-u07.g.4":"Diese Pizza schmeckt nicht.","ko-g34-u07.g.5":"Ich spiele nicht Klavier.","ko-g34-u07.g.5.task":"Verneine den Satz mit 안.","ko-g34-u07.g.6":"Heute ist es nicht kalt.","ko-g34-u07.g.6.task":"Verneine den Satz mit 안.","ko-g34-u07.g.7":"Mein großer Bruder macht keinen Sport.","ko-g34-u07.g.7.task":"Verneine den Satz. 안 steht direkt vor 해요.","ko-g34-u08.title":"Irgendwohin gehen: 에 가요","ko-g34-u08.tip":"Busan ist Koreas große Stadt am Meer, und die Insel Jeju (제주도) ist ein beliebtes Ziel für Familienreisen.","ko-g34-u08.w.0":"Markt","ko-g34-u08.w.1":"Supermarkt","ko-g34-u08.w.2":"Schwimmbad","ko-g34-u08.w.3":"Kino","ko-g34-u08.w.4":"Museum","ko-g34-u08.w.5":"Zoo","ko-g34-u08.w.6":"Firma, Büro","ko-g34-u08.w.7":"Seoul","ko-g34-u08.w.8":"Reise","ko-g34-u08.w.9":"Wochenende","ko-g34-u08.s.0":"Am Wochenende gehe ich in den Zoo.","ko-g34-u08.s.1":"Mama geht auf den Markt.","ko-g34-u08.s.2":"Papa geht ins Büro.","ko-g34-u08.s.3":"Im Sommer gehe ich ins Schwimmbad.","ko-g34-u08.s.4":"Wohin gehst du morgen?","ko-g34-u08.s.5":"Ich gehe ins Museum.","ko-g34-u08.s.6":"Morgen fahre ich nach Seoul.","ko-g34-u08.s.7":"Lass uns zusammen ins Kino gehen!","ko-g34-u08.g.title":"Irgendwohin gehen: 에 가요 · 에 와요","ko-g34-u08.g.x.0":"Setz 에 hinter einen Ort, um zu sagen, wohin du gehst: 학교에 가요 (ich gehe zur Schule).","ko-g34-u08.g.x.1":"에 bleibt immer gleich, ob mit oder ohne unteren Buchstaben: 시장에, 마트에.","ko-g34-u08.g.x.2":"Frag mit 어디: 어디에 가요? — Wohin gehst du? Für „kommen“ nimm 와요: 집에 와요.","ko-g34-u08.g.0":"Ich gehe zur Schule.","ko-g34-u08.g.1":"Ich gehe in den Zoo.","ko-g34-u08.g.2":"Wohin gehst du?","ko-g34-u08.g.3":"Mein Freund kommt zu mir nach Hause.","ko-g34-u08.g.4":"Wir gehen ins Schwimmbad.","ko-g34-u08.g.5":"Morgen gehe ich ins Museum.","ko-g34-u08.g.5.task":"Ersetze 극장 (Kino) durch 박물관 (Museum).","ko-g34-u08.g.6":"Mama geht auf den Markt.","ko-g34-u08.g.6.task":"Ersetze 마트 durch 시장 (Markt).","ko-g34-u08.g.7":"Mein Freund kommt zu uns nach Hause.","ko-g34-u08.g.7.task":"Ersetze 가요 (gehen) durch 와요 (kommen).","ko-g34-u08.st.title":"Pläne fürs Wochenende","ko-g34-u08.st.l.0":"Wohin gehst du am Wochenende?","ko-g34-u08.st.l.1":"Ich gehe in den Zoo. Da gibt es Pandas!","ko-g34-u08.st.l.2":"Wow, toll! Mit wem gehst du?","ko-g34-u08.st.l.3":"Mit meinem Papa und meinem kleinen Bruder. Und du, Jiwoo?","ko-g34-u08.st.l.4":"Ich fahre zu meiner Oma. Sie wohnt in Busan.","ko-g34-u08.st.l.5":"Das Meer in Busan ist wunderschön!","ko-g34-u08.st.q.0":"Wohin geht Hajun?","ko-g34-u08.st.q.0.o.0":"동물원","ko-g34-u08.st.q.0.o.1":"바다","ko-g34-u08.st.q.0.o.2":"시장","ko-g34-u08.st.q.1":"Wo wohnt Jiwoos Oma?","ko-g34-u08.st.q.1.o.0":"부산","ko-g34-u08.st.q.1.o.1":"서울","ko-g34-u08.st.q.1.o.2":"제주도","ko-g34-u09.title":"Wo ist es?","ko-g34-u09.tip":"Spiel Verstecken mit einem Spielzeug: Versteck es und gib Hinweise auf Koreanisch — 의자 아래에 있어요! 책상 위에 있어요!","ko-g34-u09.w.0":"auf, über","ko-g34-u09.w.1":"unter","ko-g34-u09.w.2":"neben","ko-g34-u09.w.3":"vor","ko-g34-u09.w.4":"hinter","ko-g34-u09.w.5":"drinnen, in","ko-g34-u09.w.6":"draußen","ko-g34-u09.w.7":"hier","ko-g34-u09.w.8":"da (bei dir)","ko-g34-u09.w.9":"dort drüben","ko-g34-u09.s.0":"Die Katze ist auf dem Bett.","ko-g34-u09.s.1":"Die Katze ist unter dem Sofa.","ko-g34-u09.s.2":"Der Bleistift ist in der Tasche.","ko-g34-u09.s.3":"Vor unserem Haus ist ein Park.","ko-g34-u09.s.4":"Mama setzt sich neben mich.","ko-g34-u09.s.5":"Das Hündchen ist hinter der Tür.","ko-g34-u09.s.6":"Das Badezimmer ist dort drüben.","ko-g34-u09.s.7":"Mama ist draußen.","ko-g34-u09.g.title":"Wo Dinge sind: 에 있어요 · 위 / 아래 / 옆","ko-g34-u09.g.x.0":"Mit 에 있어요 sagst du, wo etwas ist: 고양이가 방에 있어요 (die Katze ist im Zimmer).","ko-g34-u09.g.x.1":"Für eine genaue Stelle nennst du zuerst die Sache, dann die Lage, dann 에: 책상 위에 (auf dem Tisch), 의자 아래에 (unter dem Stuhl).","ko-g34-u09.g.x.2":"Lagewörter: 위 auf, 아래 unter, 옆 neben, 앞 vor, 뒤 hinter, 안 drinnen, 밖 draußen.","ko-g34-u09.g.0":"Das Buch liegt auf dem Tisch.","ko-g34-u09.g.1":"Der Ball ist unter dem Stuhl.","ko-g34-u09.g.2":"Die Katze ist in der Kiste.","ko-g34-u09.g.3":"Mein Freund ist neben mir.","ko-g34-u09.g.4":"Hinter dem Baum ist ein Hündchen.","ko-g34-u09.g.5":"Die Milch ist im Kühlschrank.","ko-g34-u09.g.5.task":"Stell die Milch in den Kühlschrank: nimm 안.","ko-g34-u09.g.6":"Der Park ist vor der Schule.","ko-g34-u09.g.6.task":"Leg den Park vor die Schule: nimm 앞.","ko-g34-u09.g.7":"Sind die Schuhe neben der Tür?","ko-g34-u09.g.7.task":"Mach daraus eine Frage.","ko-g34-u10.title":"Wo man etwas tut: 에서","ko-g34-u10.tip":"에 ist fürs Hingehen oder Dasein (학교에 가요). 에서 ist dafür, dort etwas zu tun (학교에서 공부해요).","ko-g34-u10.w.0":"Schulhof","ko-g34-u10.w.1":"Restaurant","ko-g34-u10.w.2":"Café","ko-g34-u10.w.3":"Strand","ko-g34-u10.w.4":"Turnhalle","ko-g34-u10.w.5":"Basketball","ko-g34-u10.w.6":"malen","ko-g34-u10.w.7":"sich ausruhen","ko-g34-u10.w.8":"machen (ein Foto)","ko-g34-u10.w.9":"singen","ko-g34-u10.s.0":"Ich spiele auf dem Schulhof.","ko-g34-u10.s.1":"Ich esse kalte Nudeln im Restaurant.","ko-g34-u10.s.2":"Ich lese Bücher in der Bücherei.","ko-g34-u10.s.3":"Ich baue am Strand eine Sandburg.","ko-g34-u10.s.4":"Ich ruhe mich zu Hause aus.","ko-g34-u10.s.5":"Ich male im Park.","ko-g34-u10.s.6":"Ich springe in der Turnhalle Seil.","ko-g34-u10.s.7":"Wo treffen wir uns?","ko-g34-u10.g.title":"Wo etwas passiert: 에서","ko-g34-u10.g.x.0":"Setz 에서 hinter den Ort, an dem du etwas tust: 식당에서 먹어요 (ich esse im Restaurant).","ko-g34-u10.g.x.1":"Nimm 에 mit 가요, 와요 und 있어요: 식당에 가요, 식당에 있어요.","ko-g34-u10.g.x.2":"Schneller Test: Wenn dort jemand etwas tut, ist es 에서.","ko-g34-u10.g.0":"Ich esse im Restaurant.","ko-g34-u10.g.1":"Ich spiele auf dem Schulhof Fußball.","ko-g34-u10.g.2":"Ich trinke im Café Saft.","ko-g34-u10.g.3":"Ich gehe in die Bücherei.","ko-g34-u10.g.4":"Mein großer Bruder ist in seinem Zimmer.","ko-g34-u10.g.5":"Ich mache Fotos am Strand.","ko-g34-u10.g.5.task":"Ersetze 공원 (Park) durch 바닷가 (Strand).","ko-g34-u10.g.6":"Ich spiele zu Hause mit meinem Freund.","ko-g34-u10.g.6.task":"Mach daraus „zu Hause spielen“: nimm 에서 und 놀아요.","ko-g34-u10.g.7":"Ich spiele in der Turnhalle Basketball.","ko-g34-u10.g.7.task":"Sag, was du dort machst: 농구를 해요 (Basketball spielen).","ko-g34-u11.title":"Dinge zählen","ko-g34-u11.tip":"Für Geld gibt es eine andere Zahlenreihe (천 = 1.000): 삼천 원 sind 3.000 Won. Zum Zählen von Dingen nimmt man 한, 두, 세, 네.","ko-g34-u11.w.0":"ein (vor einem Zählwort)","ko-g34-u11.w.1":"zwei (vor einem Zählwort)","ko-g34-u11.w.2":"drei (vor einem Zählwort)","ko-g34-u11.w.3":"vier (vor einem Zählwort)","ko-g34-u11.w.4":"Personen (Zählwort)","ko-g34-u11.w.5":"Tiere (Zählwort)","ko-g34-u11.w.6":"Bücher (Zählwort)","ko-g34-u11.w.7":"Blätter (Zählwort)","ko-g34-u11.w.8":"Jahre alt (Zählwort)","ko-g34-u11.w.9":"wie viele","ko-g34-u11.s.0":"Einen Apfel, bitte.","ko-g34-u11.s.1":"Wir sind vier Personen in meiner Familie.","ko-g34-u11.s.2":"Da sind zwei Katzen.","ko-g34-u11.s.3":"Wie alt bist du?","ko-g34-u11.s.4":"Ich bin neun Jahre alt.","ko-g34-u11.s.5":"Ich lese drei Bücher.","ko-g34-u11.s.6":"Ein Blatt Papier, bitte.","ko-g34-u11.s.7":"Da sind zehn Schüler.","ko-g34-u11.g.title":"Zählen: Zahl + Zählwort","ko-g34-u11.g.x.0":"Im Koreanischen zählt man mit einem Zählwort nach der Zahl: 사과 두 개 (zwei Äpfel), 학생 세 명 (drei Schüler).","ko-g34-u11.g.x.1":"하나, 둘, 셋, 넷 werden vor einem Zählwort kürzer: 한, 두, 세, 네.","ko-g34-u11.g.x.2":"Zählwörter: 개 Dinge, 명 Personen, 마리 Tiere, 권 Bücher, 장 Blätter Papier, 살 Jahre alt.","ko-g34-u11.g.0":"Zwei Äpfel, bitte.","ko-g34-u11.g.1":"Da sind drei Schüler.","ko-g34-u11.g.2":"Da ist ein Hündchen.","ko-g34-u11.g.3":"Ich bin acht Jahre alt.","ko-g34-u11.g.4":"Da sind vier Bücher.","ko-g34-u11.g.5":"Da sind drei Katzen.","ko-g34-u11.g.5.task":"Mach daraus drei Katzen.","ko-g34-u11.g.6":"Zwei Blatt Papier, bitte.","ko-g34-u11.g.6.task":"Bitte um zwei Blätter.","ko-g34-u11.g.7":"Vier Freunde kommen.","ko-g34-u11.g.7.task":"Mach daraus vier Freunde.","ko-g34-u11.st.title":"In der Bäckerei","ko-g34-u11.st.l.0":"Hallo! Zwei Brötchen, bitte.","ko-g34-u11.st.l.1":"Welche denn?","ko-g34-u11.st.l.2":"Eins von diesen Cremebrötchen und eins von den Schokobrötchen da.","ko-g34-u11.st.l.3":"Bitte schön. Das macht 3.000 Won.","ko-g34-u11.st.l.4":"Und eine Milch, bitte.","ko-g34-u11.st.l.5":"Gut, das macht zusammen 4.000 Won.","ko-g34-u11.st.q.0":"Wie viele Brötchen kauft Seoyeon?","ko-g34-u11.st.q.0.o.0":"두 개","ko-g34-u11.st.q.0.o.1":"세 개","ko-g34-u11.st.q.0.o.2":"한 개","ko-g34-u11.st.q.1":"Was kauft sie noch?","ko-g34-u11.st.q.1.o.0":"우유","ko-g34-u11.st.q.1.o.1":"주스","ko-g34-u11.st.q.1.o.2":"케이크","ko-g34-u12.title":"Wie spät ist es?","ko-g34-u12.tip":"Stunden zählt man mit 한, 두, 세 (den Zählzahlen), Minuten aber mit 일, 이, 삼 (der anderen Reihe). 3:10 Uhr ist also 세 시 십 분.","ko-g34-u12.w.0":"Uhr (Stunde)","ko-g34-u12.w.1":"Minute","ko-g34-u12.w.2":"halb (nach der Stunde)","ko-g34-u12.w.3":"jetzt","ko-g34-u12.w.4":"vormittags","ko-g34-u12.w.5":"nachmittags","ko-g34-u12.w.6":"Mittagessen","ko-g34-u12.w.7":"Abend, Abendessen","ko-g34-u12.w.8":"früh","ko-g34-u12.w.9":"spät","ko-g34-u12.s.0":"Wie spät ist es jetzt?","ko-g34-u12.s.1":"Es ist ein Uhr.","ko-g34-u12.s.2":"Treffen wir uns um halb drei.","ko-g34-u12.s.3":"Ich gehe um acht Uhr morgens zur Schule.","ko-g34-u12.s.4":"Ich esse um eins zu Mittag.","ko-g34-u12.s.5":"Treffen wir uns um vier Uhr nachmittags.","ko-g34-u12.s.6":"Am Abend mache ich meine Hausaufgaben.","ko-g34-u12.s.7":"Heute gehe ich spät ins Bett.","ko-g34-u12.g.title":"Die Uhrzeit sagen: 몇 시예요?","ko-g34-u12.g.x.0":"Die Stunde sagst du mit den kurzen Zählzahlen + 시: 한 시, 두 시, 세 시, 열두 시.","ko-g34-u12.g.x.1":"„Halb“ heißt 반: 두 시 반 (2:30 Uhr). Minuten nehmen die andere Zahlenreihe: 오 분, 십 분.","ko-g34-u12.g.x.2":"Häng 에 an für „um“: 일곱 시에 일어나요 (ich stehe um sieben auf).","ko-g34-u12.g.0":"Es ist jetzt ein Uhr.","ko-g34-u12.g.1":"Es ist halb vier.","ko-g34-u12.g.2":"Ich stehe um sieben auf.","ko-g34-u12.g.3":"Ich esse um zwölf zu Mittag.","ko-g34-u12.g.4":"Um wie viel Uhr treffen wir uns?","ko-g34-u12.g.5":"Ich komme um vier nach Hause.","ko-g34-u12.g.5.task":"Ändere die Zeit auf vier Uhr.","ko-g34-u12.g.6":"Es ist halb sechs.","ko-g34-u12.g.6.task":"Gib eine halbe Stunde dazu: nimm 반.","ko-g34-u12.g.7":"Ich gehe um neun ins Bett.","ko-g34-u12.g.7.task":"Sag, dass du um neun schlafen gehst: nimm 에 und 자요.","ko-g34-u13.title":"Wer? Wo? Wann? Warum?","ko-g34-u13.tip":"Die nützlichste Frage in einem koreanischen Laden: 이거 얼마예요? (Wie viel kostet das?) Probier sie beim Kaufladen-Spielen zu Hause aus!","ko-g34-u13.w.0":"wer","ko-g34-u13.w.1":"wo","ko-g34-u13.w.2":"wann","ko-g34-u13.w.3":"warum","ko-g34-u13.w.4":"wie","ko-g34-u13.w.5":"was für ein","ko-g34-u13.w.6":"wie viel (Preis)","ko-g34-u13.w.7":"welcher","ko-g34-u13.w.8":"Grund","ko-g34-u13.w.9":"Antwort","ko-g34-u13.s.0":"Wer ist diese Person?","ko-g34-u13.s.1":"Wann sind die Ferien?","ko-g34-u13.s.2":"Warum bist du traurig?","ko-g34-u13.s.3":"Wie komme ich zur Bücherei?","ko-g34-u13.s.4":"Wie viel kostet das?","ko-g34-u13.s.5":"Was isst du gern?","ko-g34-u13.s.6":"Aus welchem Land kommst du?","ko-g34-u13.s.7":"Wo ist das Badezimmer?","ko-g34-u13.g.title":"Fragewörter: 누구, 어디, 언제, 왜, 어떻게, 얼마","ko-g34-u13.g.x.0":"누구 wer · 뭐 was · 어디 wo · 언제 wann · 왜 warum · 어떻게 wie · 얼마 wie viel.","ko-g34-u13.g.x.1":"Mit 이에요/예요 stehen sie am Ende: 누구예요? 어디예요? 얼마예요?","ko-g34-u13.g.x.2":"Mit anderen Verben stehen sie vor dem Verb: 어디에 가요? 왜 울어요?","ko-g34-u13.g.0":"Wer ist das?","ko-g34-u13.g.1":"Wann hast du Geburtstag?","ko-g34-u13.g.2":"Warum weinst du?","ko-g34-u13.g.3":"Wie viel kostet dieser Apfel?","ko-g34-u13.g.4":"Wie kommst du zur Schule?","ko-g34-u13.g.5":"Wohin gehst du?","ko-g34-u13.g.5.task":"Frag „wohin“: nimm 어디에.","ko-g34-u13.g.6":"Wann kommst du?","ko-g34-u13.g.6.task":"Frag „wann“: nimm 언제.","ko-g34-u13.g.7":"Wer ist die Person da?","ko-g34-u13.g.7.task":"Frag „wer“: nimm 누구예요.","ko-g34-u14.title":"Ich möchte …","ko-g34-u14.tip":"Was möchtest DU machen? Bilde drei Sätze mit -고 싶어요 über dieses Wochenende.","ko-g34-u14.w.0":"Traum","ko-g34-u14.w.1":"Wissenschaftler","ko-g34-u14.w.2":"Maler","ko-g34-u14.w.3":"Sportler, Spieler","ko-g34-u14.w.4":"Weltall","ko-g34-u14.w.5":"Freizeitpark","ko-g34-u14.w.6":"Tteokbokki (scharfe Reiskuchen)","ko-g34-u14.w.7":"halten (ein Tier), ziehen (eine Pflanze)","ko-g34-u14.w.8":"fliegen","ko-g34-u14.w.9":"Schneemann","ko-g34-u14.s.0":"Ich möchte Wissenschaftler werden.","ko-g34-u14.s.1":"Ich möchte ins Weltall fliegen.","ko-g34-u14.s.2":"Ich möchte Tteokbokki essen.","ko-g34-u14.s.3":"Ich möchte eine Katze haben.","ko-g34-u14.s.4":"Ich möchte in einen Freizeitpark gehen.","ko-g34-u14.s.5":"Was möchtest du am Wochenende machen?","ko-g34-u14.s.6":"Heute möchte ich mich ausruhen.","ko-g34-u14.s.7":"Mein Traum ist es, Maler zu werden.","ko-g34-u14.g.title":"Etwas tun wollen: -고 싶어요","ko-g34-u14.g.x.0":"Um zu sagen, dass du etwas tun möchtest, nimm 다 weg und häng 고 싶어요 an: 먹다 → 먹고 싶어요 (ich möchte essen).","ko-g34-u14.g.x.1":"Das geht bei jedem Verb gleich, mit oder ohne unteren Buchstaben: 가고 싶어요, 놀고 싶어요, 쉬고 싶어요.","ko-g34-u14.g.x.2":"„Werden wollen“ heißt 되고 싶어요: 의사가 되고 싶어요 (ich möchte Arzt werden).","ko-g34-u14.g.0":"Ich möchte Pizza essen.","ko-g34-u14.g.1":"Ich möchte ans Meer.","ko-g34-u14.g.2":"Ich möchte Maler werden.","ko-g34-u14.g.3":"Ich möchte mit meinem Freund spielen.","ko-g34-u14.g.4":"Was möchtest du machen?","ko-g34-u14.g.5":"Ich möchte ins Weltall fliegen.","ko-g34-u14.g.5.task":"Sag, dass du es möchtest: nimm -고 싶어요.","ko-g34-u14.g.6":"Ich möchte ein Hündchen haben.","ko-g34-u14.g.6.task":"Sag, dass du es möchtest: nimm -고 싶어요.","ko-g34-u14.g.7":"Ich möchte einen Schneemann bauen.","ko-g34-u14.g.7.task":"Sag, dass du es möchtest: nimm -고 싶어요.","ko-g34-u14.st.title":"Mein Traum","ko-g34-u14.st.l.0":"Kinder, was ist euer Traum?","ko-g34-u14.st.l.1":"Ich möchte Fußballspieler werden!","ko-g34-u14.st.l.2":"Ich möchte Wissenschaftlerin werden. Ich möchte ins Weltall fliegen.","ko-g34-u14.st.l.3":"Ich möchte Malerin werden.","ko-g34-u14.st.l.4":"Das sind alles wunderbare Träume!","ko-g34-u14.st.q.0":"Was möchte Seoyeon werden?","ko-g34-u14.st.q.0.o.0":"과학자","ko-g34-u14.st.q.0.o.1":"화가","ko-g34-u14.st.q.0.o.2":"축구 선수","ko-g34-u14.st.q.1":"Wer möchte Maler werden?","ko-g34-u14.st.q.1.o.0":"지우","ko-g34-u14.st.q.1.o.1":"민준","ko-g34-u14.st.q.1.o.2":"서연","ko-g34-u15.title":"Mögen und nicht mögen","ko-g34-u15.tip":"Macht mit der Familie eine „Mag ich / Mag ich nicht“-Liste: 아빠는 커피를 좋아해요. 저는 벌레를 싫어해요!","ko-g34-u15.w.0":"mögen","ko-g34-u15.w.1":"nicht mögen","ko-g34-u15.w.2":"Karotte","ko-g34-u15.w.3":"Gemüse","ko-g34-u15.w.4":"Chili","ko-g34-u15.w.5":"Schokolade","ko-g34-u15.w.6":"Märchen","ko-g34-u15.w.7":"Zeichentrick, Comic","ko-g34-u15.w.8":"Käfer, Insekt","ko-g34-u15.w.9":"am liebsten, am meisten","ko-g34-u15.s.0":"Ich mag Schokolade.","ko-g34-u15.s.1":"Papa mag Karotten.","ko-g34-u15.s.2":"Welche Märchen magst du?","ko-g34-u15.s.3":"Meine große Schwester hat Angst vor Käfern.","ko-g34-u15.s.4":"Mein großer Bruder mag Märchen.","ko-g34-u15.s.5":"Am liebsten mag ich Wassermelone.","ko-g34-u15.s.6":"Ich mag auch Gemüse.","ko-g34-u15.s.7":"Chilis sind zu scharf.","ko-g34-u15.g.title":"Mögen und nicht mögen: 좋아해요 · 싫어해요","ko-g34-u15.g.x.0":"Nimm 을/를 좋아해요 für Dinge, die du magst: 사과를 좋아해요.","ko-g34-u15.g.x.1":"Nimm 을/를 싫어해요 für Dinge, die du nicht magst: 벌레를 싫어해요.","ko-g34-u15.g.x.2":"좋아요 heißt auch „Ich mag es“: 이 노래가 좋아요. Bei 좋아요 nimmst du 이/가 statt 을/를.","ko-g34-u15.g.0":"Ich mag Katzen.","ko-g34-u15.g.1":"Mein kleiner Bruder hasst Karotten.","ko-g34-u15.g.2":"Ich mag Schokolade.","ko-g34-u15.g.3":"Ich mag dieses Lied.","ko-g34-u15.g.4":"Welche Zeichentrickfilme magst du?","ko-g34-u15.g.5":"Ich mag keine Käfer.","ko-g34-u15.g.5.task":"Sag, dass du sie nicht magst.","ko-g34-u15.g.6":"Mein großer Bruder mag Gemüse.","ko-g34-u15.g.6.task":"Ersetze 고기 (Fleisch) durch 채소 (Gemüse).","ko-g34-u15.g.7":"Am liebsten mag ich Erdbeeren.","ko-g34-u15.g.7.task":"Sag „am liebsten“: füge 제일 hinzu.","ko-g34-u16.title":"Gestern habe ich …: die Vergangenheit","ko-g34-u16.tip":"Hör auf den ㅆ-Laut in der Vergangenheit: 갔어요, 봤어요, 했어요. Dieses ㅆ ist wie ein kleines „ge-…-t“!","ko-g34-u16.w.0":"letzte Woche","ko-g34-u16.w.1":"gerade eben","ko-g34-u16.w.2":"machte","ko-g34-u16.w.3":"ging","ko-g34-u16.w.4":"aß","ko-g34-u16.w.5":"sah, schaute","ko-g34-u16.w.6":"kam","ko-g34-u16.w.7":"schlief","ko-g34-u16.w.8":"machte Spaß","ko-g34-u16.w.9":"Schulferien","ko-g34-u16.s.0":"Gestern habe ich einen Film geschaut.","ko-g34-u16.s.1":"Am Morgen habe ich Brot gegessen.","ko-g34-u16.s.2":"Letzte Woche war ich in Busan.","ko-g34-u16.s.3":"Ich habe alle Hausaufgaben fertig gemacht.","ko-g34-u16.s.4":"Mein Freund ist zu mir nach Hause gekommen.","ko-g34-u16.s.5":"Gestern Abend bin ich früh ins Bett gegangen.","ko-g34-u16.s.6":"Die Ferien haben richtig Spaß gemacht.","ko-g34-u16.s.7":"Ich habe Mama gerade eben getroffen.","ko-g34-u16.g.title":"Die Vergangenheit: -았어요 / -었어요 / 했어요","ko-g34-u16.g.x.0":"Für die Vergangenheit änderst du die 요-Endung: 가요 → 갔어요, 먹어요 → 먹었어요.","ko-g34-u16.g.x.1":"Verben mit ㅏ oder ㅗ als letztem Vokal bekommen 았어요 (놀다 → 놀았어요, 보다 → 봤어요). Andere Verben bekommen 었어요 (먹다 → 먹었어요).","ko-g34-u16.g.x.2":"하다-Verben werden zu 했어요: 공부하다 → 공부했어요.","ko-g34-u16.g.0":"Gestern bin ich in den Park gegangen.","ko-g34-u16.g.1":"Ich habe gefrühstückt.","ko-g34-u16.g.2":"Ich habe einen Film geschaut.","ko-g34-u16.g.3":"Ich habe meine Hausaufgaben gemacht.","ko-g34-u16.g.4":"Ich habe mit meinem Freund gespielt.","ko-g34-u16.g.5":"Ich habe ein Buch gelesen.","ko-g34-u16.g.5.task":"Setz den Satz in die Vergangenheit.","ko-g34-u16.g.6":"Mein kleiner Bruder ist früh ins Bett gegangen.","ko-g34-u16.g.6.task":"Setz den Satz in die Vergangenheit.","ko-g34-u16.g.7":"Papa hat gekocht.","ko-g34-u16.g.7.task":"Setz den Satz in die Vergangenheit.","ko-g34-u16.st.title":"Wie waren deine Ferien?","ko-g34-u16.st.l.0":"Hattet ihr schöne Ferien?","ko-g34-u16.st.l.1":"Ja! Ich war auf der Insel Jeju.","ko-g34-u16.st.l.2":"Wow, was hast du auf Jeju gemacht?","ko-g34-u16.st.l.3":"Ich bin im Meer geschwommen. Ich habe auch viele Mandarinen gegessen.","ko-g34-u16.st.l.4":"Ich war bei meiner Oma. Ich habe mit dem Hündchen gespielt.","ko-g34-u16.st.l.5":"Die Ferien haben richtig Spaß gemacht!","ko-g34-u16.st.q.0":"Wohin ist Hajun gefahren?","ko-g34-u16.st.q.0.o.0":"제주도","ko-g34-u16.st.q.0.o.1":"서울","ko-g34-u16.st.q.0.o.2":"할머니 집","ko-g34-u16.st.q.1":"Womit hat Jiwoo gespielt?","ko-g34-u16.st.q.1.o.0":"강아지","ko-g34-u16.st.q.1.o.1":"고양이","ko-g34-u16.st.q.1.o.2":"공","ko-g34-u17.title":"Ich werde …: die Zukunft","ko-g34-u17.tip":"Vergangenheit, Gegenwart, Zukunft: 갔어요 (ging) → 가요 (gehe) → 갈 거예요 (werde gehen). Sag alle drei für 먹다 und 하다!","ko-g34-u17.w.0":"nächste Woche","ko-g34-u17.w.1":"nächstes Jahr","ko-g34-u17.w.2":"Plan","ko-g34-u17.w.3":"Test","ko-g34-u17.w.4":"Camping","ko-g34-u17.w.5":"Zelt","ko-g34-u17.w.6":"Üben","ko-g34-u17.w.7":"Umzug","ko-g34-u17.w.8":"wahrscheinlich","ko-g34-u17.w.9":"bald","ko-g34-u17.s.0":"Morgen gehe ich zelten.","ko-g34-u17.s.1":"Am Wochenende werde ich Klavier üben.","ko-g34-u17.s.2":"Es wird wahrscheinlich regnen.","ko-g34-u17.s.3":"Nächste Woche gibt es einen Test.","ko-g34-u17.s.4":"Ich werde im Zelt schlafen.","ko-g34-u17.s.5":"Wir werden bald zu Abend essen.","ko-g34-u17.s.6":"Nächstes Jahr werde ich zehn.","ko-g34-u17.s.7":"Was wirst du in den Ferien machen?","ko-g34-u17.g.title":"Die Zukunft: -(으)ㄹ 거예요","ko-g34-u17.g.x.0":"Um über die Zukunft zu sprechen, nimm 다 weg und häng ㄹ 거예요 an: 가다 → 갈 거예요, 하다 → 할 거예요.","ko-g34-u17.g.x.1":"Endet der Stamm auf einen unteren Buchstaben, häng 을 거예요 an: 먹다 → 먹을 거예요, 읽다 → 읽을 거예요.","ko-g34-u17.g.x.2":"Es kann auch „wahrscheinlich“ heißen: 비가 올 거예요 (es wird wahrscheinlich regnen).","ko-g34-u17.g.0":"Morgen werde ich in den Park gehen.","ko-g34-u17.g.1":"Zum Abendessen werde ich Pizza essen.","ko-g34-u17.g.2":"Am Wochenende werde ich lernen.","ko-g34-u17.g.3":"Es wird wahrscheinlich schneien.","ko-g34-u17.g.4":"Ich werde ein Buch lesen.","ko-g34-u17.g.5":"Morgen werde ich meinen Freund treffen.","ko-g34-u17.g.5.task":"Mach daraus morgen: nimm 내일 und -ㄹ 거예요.","ko-g34-u17.g.6":"Ich werde zelten gehen.","ko-g34-u17.g.6.task":"Setz den Satz in die Zukunft.","ko-g34-u17.g.7":"In den Ferien werde ich schwimmen lernen.","ko-g34-u17.g.7.task":"Setz den Satz in die Zukunft.","ko-g34-u18.title":"Und, mit, auch","ko-g34-u18.tip":"Erzähl deinen Morgen als eine lange Kette: 일어나고, 씻고, 옷을 입고, 학교에 가요!","ko-g34-u18.w.0":"aufstehen","ko-g34-u18.w.1":"sich waschen","ko-g34-u18.w.2":"anziehen (Kleidung)","ko-g34-u18.w.3":"Zähne putzen","ko-g34-u18.w.4":"aufräumen","ko-g34-u18.w.5":"duschen","ko-g34-u18.w.6":"und (dann)","ko-g34-u18.w.7":"und, mit","ko-g34-u18.w.8":"auch","ko-g34-u18.w.9":"zusammen","ko-g34-u18.s.0":"Ich stehe auf und wasche mir das Gesicht.","ko-g34-u18.s.1":"Ich wasche mir die Hände und esse.","ko-g34-u18.s.2":"Ich nehme Milch und einen Apfel.","ko-g34-u18.s.3":"Ich komme auch mit.","ko-g34-u18.s.4":"Ich ziehe Socken an und gehe raus.","ko-g34-u18.s.5":"Ich räume mein Zimmer auf und ruhe mich aus.","ko-g34-u18.s.6":"Ich gehe mit Papa in den Park.","ko-g34-u18.s.7":"Ich lese ein Buch und gehe schlafen.","ko-g34-u18.g.title":"Und: -고 · 하고 · 도","ko-g34-u18.g.x.0":"Um zwei Handlungen zu verbinden, nimm 다 weg und häng 고 an: 먹다 → 먹고. 밥을 먹고 양치해요 (ich esse und putze mir die Zähne).","ko-g34-u18.g.x.1":"Um zwei Nomen zu verbinden, nimm 하고: 빵하고 우유 (Brot und Milch). 하고 heißt auch „mit“: 엄마하고 가요.","ko-g34-u18.g.x.2":"도 heißt „auch“ und steht anstelle von 은/는, 이/가 oder 을/를: 저도 좋아요 (ich mag es auch).","ko-g34-u18.g.0":"Ich esse und putze mir dann die Zähne.","ko-g34-u18.g.1":"Ich ziehe mich an und gehe zur Schule.","ko-g34-u18.g.2":"Ich esse Brot und trinke Milch.","ko-g34-u18.g.3":"Ich möchte auch mitgehen.","ko-g34-u18.g.4":"Ich gehe mit Mama auf den Markt.","ko-g34-u18.g.5":"Ich mache meine Hausaufgaben und spiele dann.","ko-g34-u18.g.5.task":"Verbinde die beiden Sätze mit -고.","ko-g34-u18.g.6":"Ich dusche und gehe dann ins Bett.","ko-g34-u18.g.6.task":"Verbinde die beiden Sätze mit -고.","ko-g34-u18.g.7":"Mein kleiner Bruder kommt auch.","ko-g34-u18.g.7.task":"Sag „auch“: nimm 도.","ko-g34-u19.title":"Bitte …","ko-g34-u19.tip":"Zwei Zauberwörter für Korea: 주세요 (geben Sie mir bitte) und 천천히 말해 주세요 (sprechen Sie bitte langsam). Sag sie mit einem Lächeln!","ko-g34-u19.w.0":"geben Sie mir bitte","ko-g34-u19.w.1":"bitte (macht eine Bitte freundlicher)","ko-g34-u19.w.2":"setzen Sie sich bitte","ko-g34-u19.w.3":"kommen Sie bitte","ko-g34-u19.w.4":"warten Sie bitte","ko-g34-u19.w.5":"leise","ko-g34-u19.w.6":"langsam","ko-g34-u19.w.7":"noch einmal","ko-g34-u19.w.8":"einen Moment","ko-g34-u19.w.9":"helfen Sie mir bitte","ko-g34-u19.s.0":"Ein Glas Milch, bitte.","ko-g34-u19.s.1":"Bitte nehmen Sie Platz.","ko-g34-u19.s.2":"Willkommen, kommen Sie herein.","ko-g34-u19.s.3":"Bitte warten Sie hier.","ko-g34-u19.s.4":"Bitte etwas langsamer.","ko-g34-u19.s.5":"Bitte sagen Sie es noch einmal.","ko-g34-u19.s.6":"Bitte seid in der Bücherei leise.","ko-g34-u19.s.7":"Bitte helfen Sie mir!","ko-g34-u19.g.title":"Bitte tun: -(으)세요 · -아/어 주세요","ko-g34-u19.g.x.0":"Um jemanden höflich um etwas zu bitten, nimm 다 weg und häng 세요 an: 가다 → 가세요, 오다 → 오세요.","ko-g34-u19.g.x.1":"Endet der Stamm auf einen unteren Buchstaben, häng 으세요 an: 앉다 → 앉으세요, 읽다 → 읽으세요.","ko-g34-u19.g.x.2":"Um einen Gefallen für dich zu bitten, nimm -아/어 주세요: 도와주세요 (helfen Sie mir bitte), 말해 주세요 (sagen Sie es mir bitte).","ko-g34-u19.g.0":"Bitte setzen Sie sich hierher.","ko-g34-u19.g.1":"Bitte kommen Sie hier entlang.","ko-g34-u19.g.2":"Bitte lesen Sie dieses Buch.","ko-g34-u19.g.3":"Bitte sprechen Sie langsam.","ko-g34-u19.g.4":"Etwas Wasser, bitte.","ko-g34-u19.g.5":"Bitte warten Sie einen Moment.","ko-g34-u19.g.5.task":"Mach eine höfliche Bitte daraus: nimm -세요.","ko-g34-u19.g.6":"Bitte waschen Sie sich die Hände.","ko-g34-u19.g.6.task":"Mach eine höfliche Bitte daraus: nimm -으세요.","ko-g34-u19.g.7":"Bitte sagen Sie es noch mal.","ko-g34-u19.g.7.task":"Bitte um einen Gefallen: nimm 주세요.","ko-g34-u19.st.title":"Im Restaurant","ko-g34-u19.st.l.0":"Willkommen! Wie viele Personen?","ko-g34-u19.st.l.1":"Drei Personen.","ko-g34-u19.st.l.2":"Bitte hier entlang. Setzen Sie sich hierher.","ko-g34-u19.st.l.3":"Einmal Bibimbap und zweimal Gimbap, bitte.","ko-g34-u19.st.l.4":"Gut, bitte warten Sie einen Moment.","ko-g34-u19.st.l.5":"Und etwas Wasser, bitte!","ko-g34-u19.st.q.0":"Wie viele Personen sind in der Familie?","ko-g34-u19.st.q.0.o.0":"세 명","ko-g34-u19.st.q.0.o.1":"두 명","ko-g34-u19.st.q.0.o.2":"네 명","ko-g34-u19.st.q.1":"Was bestellt Seoyeon?","ko-g34-u19.st.q.1.o.0":"비빔밥하고 김밥","ko-g34-u19.st.q.1.o.1":"떡볶이하고 라면","ko-g34-u19.st.q.1.o.2":"김밥 세 개","ko-g34-u20.title":"Sehr, ein bisschen, zu","ko-g34-u20.tip":"Spielt Gegenteile: Einer sagt 커요!, der andere antwortet 작아요! Dann probiert 빨라요 → 느려요.","ko-g34-u20.w.0":"groß","ko-g34-u20.w.1":"klein","ko-g34-u20.w.2":"lang","ko-g34-u20.w.3":"kurz","ko-g34-u20.w.4":"schwer","ko-g34-u20.w.5":"leicht (nicht schwer)","ko-g34-u20.w.6":"schnell","ko-g34-u20.w.7":"langsam","ko-g34-u20.w.8":"sehr","ko-g34-u20.w.9":"zu (sehr)","ko-g34-u20.s.0":"Wale sind wirklich groß.","ko-g34-u20.s.1":"Mäuse sind sehr klein.","ko-g34-u20.s.2":"Dieses Buch ist ein bisschen schwer.","ko-g34-u20.s.3":"Schildkröten sind sehr langsam.","ko-g34-u20.s.4":"Der Zug ist zu schnell.","ko-g34-u20.s.5":"Luftballons sind leicht.","ko-g34-u20.s.6":"Mein kleiner Bruder hat lange Haare.","ko-g34-u20.s.7":"Dieser Bleistift ist zu kurz.","ko-g34-u20.g.title":"Sehr, ein bisschen, zu: 아주 · 조금 · 너무","ko-g34-u20.g.x.0":"Eigenschaftswörter funktionieren schon wie Verben: 커요 (ist groß), 빨라요 (ist schnell).","ko-g34-u20.g.x.1":"Setz 아주 (sehr), 조금 (ein bisschen) oder 너무 (zu) direkt davor: 아주 커요, 조금 작아요, 너무 무거워요.","ko-g34-u20.g.x.2":"Lern sie als Paare: 커요 ↔ 작아요, 길어요 ↔ 짧아요, 빨라요 ↔ 느려요, 무거워요 ↔ 가벼워요.","ko-g34-u20.g.0":"Elefanten sind sehr groß.","ko-g34-u20.g.1":"Die Tasche ist zu schwer.","ko-g34-u20.g.2":"Schnecken sind langsam.","ko-g34-u20.g.3":"Meine Haare sind ein bisschen kurz.","ko-g34-u20.g.4":"Geparden sind wirklich schnell.","ko-g34-u20.g.5":"Diese Hose ist zu lang.","ko-g34-u20.g.5.task":"Sag „zu lang“: füge 너무 hinzu.","ko-g34-u20.g.6":"Ameisen sind sehr klein.","ko-g34-u20.g.6.task":"Mach das Gegenteil daraus.","ko-g34-u20.g.7":"Federn sind sehr leicht.","ko-g34-u20.g.7.task":"Sag „sehr leicht“: füge 아주 hinzu."},g={"ko-g56-u01.title":"Gerade jetzt: -고 있어요","ko-g56-u01.tip":"Schau dich um und beschreib, was alle gerade machen: 아빠는 요리하고 있어요. 고양이는 자고 있어요.","ko-g56-u01.w.0":"in letzter Zeit","ko-g56-u01.w.1":"Gitarre","ko-g56-u01.w.2":"Anruf","ko-g56-u01.w.3":"sich fertig machen","ko-g56-u01.w.4":"Spaziergang","ko-g56-u01.w.5":"Mittagsschlaf","ko-g56-u01.w.6":"Wäsche","ko-g56-u01.w.7":"Textnachricht","ko-g56-u01.w.8":"schicken","ko-g56-u01.w.9":"suchen","ko-g56-u01.w.10":"machen, basteln","ko-g56-u01.w.11":"lachen, lächeln","ko-g56-u01.s.0":"Was machst du gerade?","ko-g56-u01.s.1":"Mein kleiner Bruder macht einen Mittagsschlaf.","ko-g56-u01.s.2":"Mama telefoniert gerade.","ko-g56-u01.s.3":"In letzter Zeit lerne ich Gitarre.","ko-g56-u01.s.4":"Papa macht die Wäsche.","ko-g56-u01.s.5":"Mein großer Bruder ruft seinen Freund an.","ko-g56-u01.s.6":"Oma geht mit dem Hündchen spazieren.","ko-g56-u01.s.7":"Ich mache mich für die Schule fertig.","ko-g56-u01.g.title":"Was gerade passiert: -고 있어요","ko-g56-u01.g.x.0":"Um zu sagen, dass etwas gerade passiert, nimm 다 weg und häng 고 있어요 an: 먹다 → 먹고 있어요 (ich esse gerade).","ko-g56-u01.g.x.1":"Es passt auch für Dinge, die du in letzter Zeit machst: 요즘 기타를 배우고 있어요.","ko-g56-u01.g.x.2":"Für die Vergangenheit nimm 고 있었어요: 그때 자고 있었어요 (da habe ich gerade geschlafen).","ko-g56-u01.g.0":"Ich esse gerade.","ko-g56-u01.g.1":"Das Baby macht einen Mittagsschlaf.","ko-g56-u01.g.2":"Mein großer Bruder spielt Gitarre.","ko-g56-u01.g.3":"Was machst du gerade?","ko-g56-u01.g.4":"Da habe ich gerade ein Buch gelesen.","ko-g56-u01.g.5":"Mama macht gerade die Wäsche.","ko-g56-u01.g.5.task":"Sag, dass es gerade passiert: nimm -고 있어요.","ko-g56-u01.g.6":"Ich schicke meinem Freund gerade eine Nachricht.","ko-g56-u01.g.6.task":"Sag, dass es gerade passiert: nimm -고 있어요.","ko-g56-u01.g.7":"In letzter Zeit lerne ich schwimmen.","ko-g56-u01.g.7.task":"Sag, dass du es in letzter Zeit machst: nimm -고 있어요.","ko-g56-u02.title":"Können und nicht können","ko-g56-u02.tip":"Du liest gerade Hangul — die Buchstaben, die König Sejong gemacht hat, damit alle lesen können. Ziemlich cool!","ko-g56-u02.w.0":"Hangul (das koreanische Alphabet)","ko-g56-u02.w.1":"Buchstabe, Schriftzeichen","ko-g56-u02.w.2":"Laut","ko-g56-u02.w.3":"Form","ko-g56-u02.w.4":"König","ko-g56-u02.w.5":"das einfache Volk (altes Wort)","ko-g56-u02.w.6":"leicht, mühelos","ko-g56-u02.w.7":"Autofahren","ko-g56-u02.w.8":"Pfeifen","ko-g56-u02.w.9":"Fremdsprache","ko-g56-u02.w.10":"machte, schuf","ko-g56-u02.w.11":"klug","ko-g56-u02.s.0":"Mein kleiner Bruder kann ein bisschen Hangul lesen.","ko-g56-u02.s.1":"Mein kleiner Bruder kann noch nicht Fahrrad fahren.","ko-g56-u02.s.2":"Mama kann nicht Auto fahren.","ko-g56-u02.s.3":"Mein großer Bruder kann gut pfeifen.","ko-g56-u02.s.4":"Es regnet, darum kann ich nicht draußen spielen.","ko-g56-u02.s.5":"Mein großer Bruder kann zwei Fremdsprachen sprechen.","ko-g56-u02.s.6":"Hangul kann man leicht lernen.","ko-g56-u02.s.7":"Diesen Brief kannst du leicht lesen.","ko-g56-u02.g.title":"Können und nicht können: -(으)ㄹ 수 있어요 / 없어요","ko-g56-u02.g.x.0":"Um zu sagen, dass du etwas kannst, nimm 다 weg und häng ㄹ 수 있어요 an: 가다 → 갈 수 있어요, 하다 → 할 수 있어요.","ko-g56-u02.g.x.1":"Nach einem unteren Buchstaben kommt 을 수 있어요: 읽다 → 읽을 수 있어요. Stämme auf ㄹ bleiben gleich: 놀다 → 놀 수 있어요.","ko-g56-u02.g.x.2":"Für „nicht können“ wird 있어요 zu 없어요: 갈 수 없어요. Du kannst auch 못 vor das Verb setzen: 못 가요.","ko-g56-u02.g.0":"Ich kann Hangul lesen.","ko-g56-u02.g.1":"Papa kann Auto fahren.","ko-g56-u02.g.2":"Heute kann ich nicht spielen.","ko-g56-u02.g.3":"Kannst du pfeifen?","ko-g56-u02.g.4":"Ich kann nicht schwimmen.","ko-g56-u02.g.5":"Mein kleiner Bruder kann nicht Fahrrad fahren.","ko-g56-u02.g.5.task":"Mach daraus „kann nicht“: nimm 없어요.","ko-g56-u02.g.6":"Mein großer Bruder kann eine Fremdsprache sprechen.","ko-g56-u02.g.6.task":"Sag, dass er es kann: nimm -ㄹ 수 있어요.","ko-g56-u02.g.7":"Kannst du diesen Brief lesen?","ko-g56-u02.g.7.task":"Frag „kannst du“: nimm -을 수 있어요.","ko-g56-u02.r.ko":"Das Geheimnis von Hangul","ko-g56-u02.r.genre":"Geschichte","ko-g56-u02.r.p.0":"Vor langer Zeit schrieben die Koreaner mit chinesischen Schriftzeichen. Es gab sehr viele Zeichen, und sie waren schwer. Darum konnten viele einfache Leute nicht lesen.","ko-g56-u02.r.p.1":"König Sejong von Joseon liebte sein Volk. Darum schuf er 1443 einfache Buchstaben. Diese Buchstaben sind Hangul.","ko-g56-u02.r.p.2":"Die Konsonanten entstanden, indem man die Form von Mund und Zunge bei jedem Laut ansah. ㄱ zeigt zum Beispiel, wie der hintere Teil der Zunge den Hals versperrt. Die Vokale entstanden aus dem Himmel, der Erde und dem Menschen.","ko-g56-u02.r.p.3":"Mit nur 24 Buchstaben kann man mit Hangul fast jeden Laut schreiben. Darum kann jeder in ein paar Tagen lesen lernen. Am 9. Oktober, dem Hangul-Tag, feiern die Koreaner diese Buchstaben.","ko-g56-u02.r.q.3.o.0":"einfache Leute","ko-g56-u02.r.q.3.o.1":"Könige","ko-g56-u02.r.q.3.o.2":"Lehrer","ko-g56-u03.title":"Müssen: -아야 해요","ko-g56-u03.tip":"Koreanische Kinder lernen diese Verkehrsregel: Am Zebrastreifen stehen bleiben, nach links und rechts schauen und beim Überqueren die Hand heben.","ko-g56-u03.w.0":"Regel","ko-g56-u03.w.1":"einhalten (eine Regel)","ko-g56-u03.w.2":"Sicherheit","ko-g56-u03.w.3":"Helm","ko-g56-u03.w.4":"überqueren","ko-g56-u03.w.5":"Ampel","ko-g56-u03.w.6":"Zebrastreifen","ko-g56-u03.w.7":"Reihe, Schlange","ko-g56-u03.w.8":"wer dran ist","ko-g56-u03.w.9":"wichtig","ko-g56-u03.w.10":"sauber, gründlich","ko-g56-u03.w.11":"unbedingt","ko-g56-u03.s.0":"Du musst dir die Hände gründlich waschen.","ko-g56-u03.s.1":"Man muss am Zebrastreifen über die Straße gehen.","ko-g56-u03.s.2":"Beim Fahrradfahren musst du einen Helm tragen.","ko-g56-u03.s.3":"In der Mensa stellen wir uns in einer Reihe an.","ko-g56-u03.s.4":"Morgen muss ich früh zur Schule.","ko-g56-u03.s.5":"Ich muss zuerst meine Hausaufgaben machen.","ko-g56-u03.s.6":"Alle halten sich an die Regeln.","ko-g56-u03.s.7":"Wenn die Ampel grün ist, heb immer die Hand und geh hinüber.","ko-g56-u03.g.title":"Müssen: -아야 / -어야 해요","ko-g56-u03.g.x.0":"Um zu sagen, dass du etwas tun musst, nimm die 요-Form, lass 요 weg und häng 야 해요 an: 가요 → 가야 해요, 먹어요 → 먹어야 해요.","ko-g56-u03.g.x.1":"하다-Verben werden zu 해야 해요: 공부해야 해요 (ich muss lernen).","ko-g56-u03.g.x.2":"Für die Vergangenheit sag 해야 했어요: 어제 일찍 자야 했어요 (gestern musste ich früh ins Bett).","ko-g56-u03.g.0":"Du musst dir die Hände waschen.","ko-g56-u03.g.1":"Ich muss jetzt gehen.","ko-g56-u03.g.2":"Ich muss meine Hausaufgaben machen.","ko-g56-u03.g.3":"Man muss sich anstellen.","ko-g56-u03.g.4":"Du musst einen Helm tragen.","ko-g56-u03.g.5":"Morgen muss ich früh aufstehen.","ko-g56-u03.g.5.task":"Sag, dass du musst: nimm -아야 해요.","ko-g56-u03.g.6":"Man muss die Schulregeln einhalten.","ko-g56-u03.g.6.task":"Sag, dass man muss: nimm -어야 해요.","ko-g56-u03.g.7":"Gestern musste ich lernen.","ko-g56-u03.g.7.task":"Mach daraus gestern (Vergangenheit).","ko-g56-u04.title":"Wenn: -(으)면","ko-g56-u04.tip":"Bilde „wenn“-Sätze über deinen Tag: 숙제를 다 하면 게임을 해요. 비가 오면 집에서 놀아요.","ko-g56-u04.w.0":"die vier Jahreszeiten","ko-g56-u04.w.1":"deutlich","ko-g56-u04.w.2":"Kirschblüte","ko-g56-u04.w.3":"Regenzeit","ko-g56-u04.w.4":"Herbstlaub","ko-g56-u04.w.5":"Schneeballschlacht","ko-g56-u04.w.6":"warm","ko-g56-u04.w.7":"kühl, erfrischend","ko-g56-u04.w.8":"falls, angenommen","ko-g56-u04.w.9":"blühen","ko-g56-u04.w.10":"fallen","ko-g56-u04.w.11":"sich häufen","ko-g56-u04.s.0":"Wenn viel Schnee liegt, fahren wir Schlitten.","ko-g56-u04.s.1":"Wenn das Wetter warm ist, gehe ich in den Park.","ko-g56-u04.s.2":"Wenn der Sommer kommt, beginnt die Regenzeit.","ko-g56-u04.s.3":"Wenn du Durst hast, trink Wasser.","ko-g56-u04.s.4":"Wenn der Herbst kommt, fallen die Blätter.","ko-g56-u04.s.5":"Wenn wir keine Zeit haben, machen wir es morgen.","ko-g56-u04.s.6":"Wenn der Wind kühl ist, gehe ich spazieren.","ko-g56-u04.s.7":"Wenn es regnet, spielen wir zu Hause.","ko-g56-u04.g.title":"Wenn: -(으)면","ko-g56-u04.g.x.0":"Nimm 다 weg und häng 면 an für „wenn“: 오다 → 오면. 비가 오면 우산을 써요 (wenn es regnet, nehme ich einen Schirm).","ko-g56-u04.g.x.1":"Nach einem unteren Buchstaben kommt 으면: 있다 → 있으면, 먹다 → 먹으면.","ko-g56-u04.g.x.2":"Stämme auf ㄹ bekommen einfach 면: 놀다 → 놀면, 만들다 → 만들면.","ko-g56-u04.g.0":"Wenn es regnet, nehme ich einen Schirm.","ko-g56-u04.g.1":"Wenn du Zeit hast, lass uns spielen.","ko-g56-u04.g.2":"Wenn du Hunger hast, sag es mir.","ko-g56-u04.g.3":"Wenn du müde bist, ruh dich aus.","ko-g56-u04.g.4":"Wenn du diese Medizin nimmst, geht es dir bald besser.","ko-g56-u04.g.5":"Wenn der Frühling kommt, blühen die Kirschblüten.","ko-g56-u04.g.5.task":"Verbinde sie mit -면 (wenn).","ko-g56-u04.g.6":"Wenn es schneit, machen wir Schneeballschlachten.","ko-g56-u04.g.6.task":"Verbinde sie mit -면 (wenn).","ko-g56-u04.g.7":"Wenn ich mich verspäte, rufe ich an.","ko-g56-u04.g.7.task":"Verbinde sie mit -으면 (wenn).","ko-g56-u04.r.ko":"Koreas vier Jahreszeiten","ko-g56-u04.r.genre":"Kultur","ko-g56-u04.r.p.0":"Korea hat vier deutliche Jahreszeiten. Frühling, Sommer, Herbst und Winter sind alle verschieden. Wenn der Frühling kommt, wird das Wetter warm. Kirschblüten und Forsythien blühen in den Bergen und auf den Straßen. Die Leute gehen in die Parks, um die Blumen anzuschauen.","ko-g56-u04.r.p.1":"Der Sommer ist sehr heiß. Wenn die Regenzeit kommt, regnet es viel. Wenn die Regenzeit vorbei ist, gehen die Kinder an den Strand oder ins Schwimmbad.","ko-g56-u04.r.p.2":"Im Herbst ist der Wind kühl. Die Berge werden mit roten und gelben Blättern wunderschön. Der Winter ist kalt. Wenn viel Schnee liegt, bauen die Kinder Schneemänner und machen Schneeballschlachten.","ko-g56-u04.r.q.3.o.0":"buntes Herbstlaub","ko-g56-u04.r.q.3.o.1":"Kirschblüten","ko-g56-u04.r.q.3.o.2":"Schneemänner","ko-g56-u05.title":"Weil, darum: -아서","ko-g56-u05.tip":"만나서 반가워요 (Schön, dich kennenzulernen) heißt wörtlich „Weil wir uns getroffen haben, freue ich mich“ — jetzt erkennst du das -아서 darin!","ko-g56-u05.w.0":"Verschlafen","ko-g56-u05.w.1":"Zuspätkommen (zur Schule)","ko-g56-u05.w.2":"Fieber","ko-g56-u05.w.3":"Medizin","ko-g56-u05.w.4":"hinfallen","ko-g56-u05.w.5":"sich verletzen","ko-g56-u05.w.6":"rutschig","ko-g56-u05.w.7":"froh (dich zu sehen)","ko-g56-u05.w.8":"kam zu spät","ko-g56-u05.w.9":"verpassen (einen Bus)","ko-g56-u05.w.10":"darum, deshalb","ko-g56-u05.w.11":"weil","ko-g56-u05.s.0":"Ich war erkältet, darum konnte ich nicht zur Schule gehen.","ko-g56-u05.s.1":"Es hat geschneit, darum ist die Straße rutschig.","ko-g56-u05.s.2":"Ich war so müde, dass ich einen Mittagsschlaf gemacht habe.","ko-g56-u05.s.3":"Ich war spät dran, darum habe ich ein Taxi genommen.","ko-g56-u05.s.4":"Ich habe mich gefreut, meinen Freund wiederzusehen.","ko-g56-u05.s.5":"Es hat geregnet, darum bin ich zu Hause geblieben.","ko-g56-u05.s.6":"Ich bin zur Schule gegangen und habe meinen Freund getroffen.","ko-g56-u05.s.7":"Ich habe mich verletzt, darum habe ich Salbe draufgetan.","ko-g56-u05.g.title":"Weil, darum: -아서 / -어서","ko-g56-u05.g.x.0":"Um einen Grund zu nennen, nimm die 요-Form, lass 요 weg und häng 서 an: 고파요 → 고파서. 배가 고파서 먹었어요 (ich hatte Hunger, darum habe ich gegessen).","ko-g56-u05.g.x.1":"하다-Verben werden zu 해서: 피곤해서, 공부해서.","ko-g56-u05.g.x.2":"Nur das letzte Verb zeigt die Vergangenheit: 늦잠을 자서 늦었어요 — niemals 잤어서.","ko-g56-u05.g.x.3":"-아서/어서 verbindet auch Schritte der Reihe nach: 시장에 가서 과일을 샀어요 (ich ging auf den Markt und kaufte Obst).","ko-g56-u05.g.0":"Ich hatte Hunger, darum habe ich Brot gegessen.","ko-g56-u05.g.1":"Ich habe verschlafen, darum kam ich zu spät.","ko-g56-u05.g.2":"Ich hatte Fieber, darum bin ich ins Krankenhaus gegangen.","ko-g56-u05.g.3":"Ich war so müde, dass ich früh ins Bett gegangen bin.","ko-g56-u05.g.4":"Schön, dich kennenzulernen.","ko-g56-u05.g.5":"Ich habe den Bus verpasst, darum kam ich zu spät.","ko-g56-u05.g.5.task":"Verbinde sie mit -어서 (darum).","ko-g56-u05.g.6":"Die Straße war rutschig, darum bin ich hingefallen.","ko-g56-u05.g.6.task":"Verbinde sie mit -어서 (darum).","ko-g56-u05.g.7":"Ich bin auf den Markt gegangen und habe Obst gekauft.","ko-g56-u05.g.7.task":"Verbinde die Schritte mit -아서.","ko-g56-u06.title":"Aber: -지만","ko-g56-u06.tip":"Am Mondneujahr verbeugen sich Kinder vor den Älteren und sagen 새해 복 많이 받으세요 (Viel Glück im neuen Jahr).","ko-g56-u06.w.0":"Mondneujahr","ko-g56-u06.w.1":"traditioneller Feiertag","ko-g56-u06.w.2":"Chuseok (Erntedankfest)","ko-g56-u06.w.3":"Neujahrsverbeugung","ko-g56-u06.w.4":"Neujahrsgeld","ko-g56-u06.w.5":"Reiskuchensuppe","ko-g56-u06.w.6":"Hanbok (traditionelle Kleidung)","ko-g56-u06.w.7":"Verwandte","ko-g56-u06.w.8":"sich versammeln","ko-g56-u06.w.9":"bekommen","ko-g56-u06.w.10":"Tradition","ko-g56-u06.w.11":"aber, jedoch","ko-g56-u06.s.0":"Chuseok ist im Herbst.","ko-g56-u06.s.1":"Das Mondneujahr ist anstrengend, aber lustig.","ko-g56-u06.s.2":"Draußen ist es kalt, aber zu Hause warm.","ko-g56-u06.s.3":"Mein kleiner Bruder ist klein, aber stark.","ko-g56-u06.s.4":"Ich bin satt. Aber ich möchte noch mehr essen.","ko-g56-u06.s.5":"Am Mondneujahr kommen die Verwandten zusammen.","ko-g56-u06.s.6":"Ich habe mich zu Neujahr vor Opa verbeugt.","ko-g56-u06.s.7":"Ich habe viel Neujahrsgeld bekommen.","ko-g56-u06.g.title":"Aber: -지만 · 하지만","ko-g56-u06.g.x.0":"Um „aber“ innerhalb eines Satzes zu sagen, nimm 다 weg und häng 지만 an: 맛있다 → 맛있지만. 맛있지만 뜨거워요 (es ist lecker, aber heiß).","ko-g56-u06.g.x.1":"-지만 geht bei allen Verben und Eigenschaftswörtern gleich: 춥지만, 예쁘지만, 했지만.","ko-g56-u06.g.x.2":"Um einen neuen Satz mit „aber“ zu beginnen, nimm 하지만: 피곤해요. 하지만 행복해요.","ko-g56-u06.g.0":"Reiskuchensuppe ist lecker, aber heiß.","ko-g56-u06.g.1":"Es ist kalt, aber ich fühle mich gut.","ko-g56-u06.g.2":"Der Hanbok ist hübsch, aber ein bisschen unbequem.","ko-g56-u06.g.3":"Mein kleiner Bruder ist jung, aber klug.","ko-g56-u06.g.4":"Ich bin müde. Aber ich bin glücklich.","ko-g56-u06.g.5":"Lernen ist schwer, aber es macht Spaß.","ko-g56-u06.g.5.task":"Mach einen Satz daraus mit -지만.","ko-g56-u06.g.6":"Gestern hat es geregnet, aber heute ist es klar.","ko-g56-u06.g.6.task":"Mach einen Satz daraus mit -지만.","ko-g56-u06.g.7":"Mein großer Bruder ist groß, aber ich bin klein.","ko-g56-u06.g.7.task":"Mach einen Satz daraus mit -지만.","ko-g56-u06.r.ko":"Neujahrsmorgen","ko-g56-u06.r.genre":"Kultur","ko-g56-u06.r.p.0":"Es ist Neujahrsmorgen. Jiwoo ist früh aufgestanden und hat ihren Hanbok angezogen. Der Hanbok ist hübsch, aber ein bisschen unbequem. Alle Verwandten haben sich bei Opa versammelt.","ko-g56-u06.r.p.1":"Jiwoo hat sich zu Neujahr vor Opa und Oma verbeugt. „Frohes neues Jahr!“ Opa hat gelächelt und ihr Neujahrsgeld gegeben.","ko-g56-u06.r.p.2":"Am Morgen haben alle zusammen Reiskuchensuppe gegessen. In Korea sagt man, dass man ein Jahr älter wird, wenn man Reiskuchensuppe isst. Am Nachmittag hat Jiwoo mit ihren Cousins Yunnori gespielt, ein Brettspiel. Sie hat verloren, aber es hat ihr riesigen Spaß gemacht.","ko-g56-u07.title":"Größer, am größten","ko-g56-u07.tip":"Vergleich Dinge um dich herum: 아빠가 엄마보다 커요. 고양이가 강아지보다 작아요. Wer ist in deiner Familie 제일?","ko-g56-u07.w.0":"als (beim Vergleich)","ko-g56-u07.w.1":"mehr","ko-g56-u07.w.2":"weniger","ko-g56-u07.w.3":"am meisten","ko-g56-u07.w.4":"hoch, groß","ko-g56-u07.w.5":"niedrig","ko-g56-u07.w.6":"breit, geräumig","ko-g56-u07.w.7":"eng","ko-g56-u07.w.8":"Stadt","ko-g56-u07.w.9":"Land (auf dem Land)","ko-g56-u07.w.10":"Cousin","ko-g56-u07.w.11":"Vergleich","ko-g56-u07.s.0":"Papa ist größer als Mama.","ko-g56-u07.s.1":"Die Stadt ist lauter als das Land.","ko-g56-u07.s.2":"Dieses Kimchi ist weniger scharf als das andere.","ko-g56-u07.s.3":"Minjun ist der Schnellste in unserer Klasse.","ko-g56-u07.s.4":"Ein Berg ist höher als ein Hügel.","ko-g56-u07.s.5":"Von allen Tieren mag ich Katzen am liebsten.","ko-g56-u07.s.6":"Mein Zimmer ist kleiner als das von meinem kleinen Bruder.","ko-g56-u07.s.7":"Mein Cousin ist ein Jahr älter als ich.","ko-g56-u07.g.title":"Vergleichen: 보다 (더) · 제일 / 가장","ko-g56-u07.g.x.0":"Zum Vergleichen setzt du 보다 hinter das, womit du vergleichst: 형이 저보다 커요 (mein Bruder ist größer als ich).","ko-g56-u07.g.x.1":"Du kannst 더 (mehr) oder 덜 (weniger) dazunehmen: 서울이 부산보다 더 커요.","ko-g56-u07.g.x.2":"Für „am …sten“ nimm 제일 oder 가장: 제일 빨라요 (ist am schnellsten). Mit 에서 nennst du die Gruppe: 우리 반에서 제일 빨라요.","ko-g56-u07.g.0":"Mein großer Bruder ist größer als ich.","ko-g56-u07.g.1":"Seoul ist größer als Busan.","ko-g56-u07.g.2":"Heute ist es weniger kalt als gestern.","ko-g56-u07.g.3":"Minjun ist der Schnellste.","ko-g56-u07.g.4":"Am liebsten mag ich den Sommer.","ko-g56-u07.g.5":"Auf dem Land ist es ruhiger als in der Stadt.","ko-g56-u07.g.5.task":"Vergleiche mit der Stadt: füge 도시보다 hinzu.","ko-g56-u07.g.6":"Diese Straße ist breiter als die Straße dort.","ko-g56-u07.g.6.task":"Vergleiche mit der Straße dort: füge 저 길보다 hinzu.","ko-g56-u07.g.7":"Jiwoo ist die Größte in unserer Klasse.","ko-g56-u07.g.7.task":"Sag „die Größte“: füge 제일 hinzu.","ko-g56-u08.title":"Ein liebes Kind, ein lustiges Buch","ko-g56-u08.tip":"Beschreib deine Lieblingssachen: 제가 좋아하는 색, 제가 좋아하는 동물, 제가 좋아하는 음식은 …","ko-g56-u08.w.0":"neu","ko-g56-u08.w.1":"alt, gebraucht","ko-g56-u08.w.2":"früher, vor langer Zeit","ko-g56-u08.w.3":"lieb, gutherzig","ko-g56-u08.w.4":"süß, niedlich","ko-g56-u08.w.5":"berühmt","ko-g56-u08.w.6":"ruhig, still","ko-g56-u08.w.7":"laut","ko-g56-u08.w.8":"freundlich","ko-g56-u08.w.9":"langweilig","ko-g56-u08.w.10":"gleich","ko-g56-u08.w.11":"anders","ko-g56-u08.s.0":"Oma hat eine süße Katze.","ko-g56-u08.s.1":"Das liebe Kind hilft seinem kleinen Geschwisterchen.","ko-g56-u08.s.2":"Ich lese in der ruhigen Bücherei.","ko-g56-u08.s.3":"Das ist ein berühmtes Restaurant.","ko-g56-u08.s.4":"Ich mag freundliche Lehrer.","ko-g56-u08.s.5":"Der Zeichentrickfilm, den mein großer Bruder schaut, ist lustig.","ko-g56-u08.s.6":"Meine Lieblingsfarbe ist Grün.","ko-g56-u08.s.7":"Ich ziehe neue Schuhe an.","ko-g56-u08.g.title":"Ein Nomen beschreiben: -(으)ㄴ / -는","ko-g56-u08.g.x.0":"Um ein Eigenschaftswort vor ein Nomen zu stellen, nimm 다 weg und häng ㄴ an: 착하다 → 착한 아이 (ein liebes Kind), 크다 → 큰 집.","ko-g56-u08.g.x.1":"Nach einem unteren Buchstaben kommt 은: 작다 → 작은 고양이. Wörter auf 있다/없다 bekommen 는: 재미있는 책.","ko-g56-u08.g.x.2":"Für Handlungen, die gerade passieren, häng 는 an: 읽다 → 읽는 책 (das Buch, das ich lese), 좋아하다 → 좋아하는 음식 (Lieblingsessen).","ko-g56-u08.g.0":"Das ist ein liebes Kind.","ko-g56-u08.g.1":"Da ist eine kleine Katze.","ko-g56-u08.g.2":"Ich lese ein lustiges Buch.","ko-g56-u08.g.3":"Mein Lieblingsessen ist Tteokbokki.","ko-g56-u08.g.4":"Ich lerne in der ruhigen Bücherei.","ko-g56-u08.g.5":"Ich habe ein süßes Hündchen.","ko-g56-u08.g.5.task":"Stell „süß“ in einem Satz vor 강아지.","ko-g56-u08.g.6":"Das ist ein berühmtes Lied.","ko-g56-u08.g.6.task":"Sag „ein berühmtes Lied“: stell 유명한 vor 노래.","ko-g56-u08.g.7":"Das Buch, das ich gerade lese, ist lustig.","ko-g56-u08.g.7.task":"Mach einen Satz daraus: 읽는 책.","ko-g56-u09.title":"Respekt vor Älteren","ko-g56-u09.tip":"Koreanische Großeltern nennen ihre Enkel oft liebevoll 우리 강아지 (mein Hündchen). Ein süßer Spitzname!","ko-g56-u09.w.0":"Zuhause (eines Älteren)","ko-g56-u09.w.1":"Mahlzeit (eines Älteren)","ko-g56-u09.w.2":"bitte essen Sie (zu Älteren)","ko-g56-u09.w.3":"schlafen (bei Älteren)","ko-g56-u09.w.4":"da sein, bleiben (bei Älteren)","ko-g56-u09.w.5":"an, zu (einem Älteren)","ko-g56-u09.w.6":"geben (einem Älteren)","ko-g56-u09.w.7":"Alter (eines Älteren)","ko-g56-u09.w.8":"Worte (eines Älteren)","ko-g56-u09.w.9":"höfliche Sprache","ko-g56-u09.w.10":"Erwachsener","ko-g56-u09.w.11":"Enkelkind","ko-g56-u09.s.0":"Opa, bitte nimm das.","ko-g56-u09.s.1":"Die Lehrerin ist im Klassenzimmer.","ko-g56-u09.s.2":"Opa schläft gerade.","ko-g56-u09.s.3":"Ich habe Oma Blumen geschenkt.","ko-g56-u09.s.4":"Opa liest Zeitung.","ko-g56-u09.s.5":"Ich höre meiner Lehrerin gut zu.","ko-g56-u09.s.6":"Mit Erwachsenen sprechen wir höflich.","ko-g56-u09.s.7":"Wie alt ist dein Opa?","ko-g56-u09.g.title":"Respekt zeigen: -(으)세요 · 께 · besondere Wörter","ko-g56-u09.g.x.0":"Wenn du über einen älteren Menschen sprichst, häng 시 ans Verb: 가요 → 가세요, 웃어요 → 웃으세요 (Oma lächelt).","ko-g56-u09.g.x.1":"Manche Wörter ändern sich ganz: 먹어요 → 드세요, 자요 → 주무세요, 있어요 → 계세요, 집 → 댁, 나이 → 연세.","ko-g56-u09.g.x.2":"Nimm 께 für „an“ einen Älteren (할머니께 드려요) und 께서 statt 이/가 (할머니께서 웃으세요).","ko-g56-u09.g.0":"Oma, bitte iss.","ko-g56-u09.g.1":"Opa ist in seinem Zimmer.","ko-g56-u09.g.2":"Gute Nacht, Oma.","ko-g56-u09.g.3":"Ich habe meiner Lehrerin einen Brief gegeben.","ko-g56-u09.g.4":"Oma lächelt.","ko-g56-u09.g.5":"Ich gehe zu Opa nach Hause.","ko-g56-u09.g.5.task":"Nimm das respektvolle Wort für das Zuhause eines Älteren: 댁.","ko-g56-u09.g.6":"Wie alt ist deine Oma?","ko-g56-u09.g.6.task":"Nimm das respektvolle Wort für das Alter eines Älteren: 연세.","ko-g56-u09.g.7":"Ich schenke Papa ein Geschenk.","ko-g56-u09.g.7.task":"Nimm das respektvolle Verb für Geben an Ältere: 드려요.","ko-g56-u09.r.ko":"Bei Oma","ko-g56-u09.r.genre":"Geschichte","ko-g56-u09.r.p.0":"Am Samstag fuhr Hajun zu seiner Oma aufs Land. Oma wartete schon vor der Tür. „Hallo, Oma!“, grüßte Hajun laut.","ko-g56-u09.r.p.1":"Am Abend kochte Oma einen leckeren Sojabohnenpasten-Eintopf. Hajun reichte Oma einen Löffel. „Oma, bitte iss.“ Oma lächelte und sagte: „Mein Enkel ist der Beste!“","ko-g56-u09.r.p.2":"In der Nacht erzählte Oma ihm eine alte Geschichte. Hajun schlief beim Zuhören ein. Oma deckte ihn mit einer Decke zu. „Schlaf gut, mein kleines Hündchen.“","ko-g56-u09.r.q.2.o.0":"der Enkel","ko-g56-u09.r.q.2.o.1":"die Oma","ko-g56-u09.r.q.2.o.2":"der Nachbar","ko-g56-u10.title":"Probier es mal","ko-g56-u10.tip":"Frag deine Familie nach ihren Erfahrungen: 한국 음식을 먹어 봤어요? 태권도를 해 봤어요?","ko-g56-u10.w.0":"Erfahrung","ko-g56-u10.w.1":"das erste Mal","ko-g56-u10.w.2":"einmal","ko-g56-u10.w.3":"Geschmack","ko-g56-u10.w.4":"Geruch","ko-g56-u10.w.5":"erstaunlich, faszinierend","ko-g56-u10.w.6":"Bibimbap","ko-g56-u10.w.7":"Taekwondo","ko-g56-u10.w.8":"traditionelles koreanisches Haus","ko-g56-u10.w.9":"anziehen (Schuhe, Socken)","ko-g56-u10.w.10":"wie ist es?","ko-g56-u10.w.11":"Fahrgeschäft","ko-g56-u10.s.0":"Probier auch dieses Kimchi.","ko-g56-u10.s.1":"Hast du schon mal Tteokbokki probiert?","ko-g56-u10.s.2":"Ja, ich habe es einmal probiert.","ko-g56-u10.s.3":"Probier diesen Hut auf.","ko-g56-u10.s.4":"Ich möchte mal Taekwondo lernen.","ko-g56-u10.s.5":"Ich habe zum ersten Mal in einem Hanok geschlafen.","ko-g56-u10.s.6":"Wie schmeckt es?","ko-g56-u10.s.7":"Es war eine richtig erstaunliche Erfahrung.","ko-g56-u10.g.title":"Probier es: -아/어 보세요 · -아/어 봤어요","ko-g56-u10.g.x.0":"Häng 보세요 an die -아/어-Form, um „probier es mal“ zu sagen: 먹어 보세요 (probier mal), 입어 보세요 (probier es an).","ko-g56-u10.g.x.1":"봤어요 heißt, dass du es schon einmal gemacht hast: 먹어 봤어요 (das habe ich schon mal gegessen).","ko-g56-u10.g.x.2":"Frag nach Erfahrungen mit 봤어요?: 한국에 가 봤어요? — Warst du schon mal in Korea?","ko-g56-u10.g.0":"Probier diesen Reiskuchen.","ko-g56-u10.g.1":"Probier diese Kleidung an.","ko-g56-u10.g.2":"Hast du schon mal Bibimbap probiert?","ko-g56-u10.g.3":"Ich war schon mal in Korea.","ko-g56-u10.g.4":"Probier doch mal Taekwondo.","ko-g56-u10.g.5":"Ich habe schon mal in einem Hanok geschlafen.","ko-g56-u10.g.5.task":"Sag, dass du die Erfahrung gemacht hast: nimm -아 봤어요.","ko-g56-u10.g.6":"Probier diese Schuhe an.","ko-g56-u10.g.6.task":"Lade zum Ausprobieren ein: nimm -어 보세요.","ko-g56-u10.g.7":"Bist du schon mal mit diesem Fahrgeschäft gefahren?","ko-g56-u10.g.7.task":"Frag nach der Erfahrung: nimm -아 봤어요?","ko-g56-u11.title":"Wollen wir …?","ko-g56-u11.tip":"In Korea kann man sich Essen fast überallhin liefern lassen — sogar in einen Park am Fluss!","ko-g56-u11.w.0":"Picknick, Ausflug","ko-g56-u11.w.1":"Lunchbox","ko-g56-u11.w.2":"Picknickdecke","ko-g56-u11.w.3":"Brathähnchen","ko-g56-u11.w.4":"Lieferung","ko-g56-u11.w.5":"der Han-Fluss","ko-g56-u11.w.6":"steigen lassen (einen Drachen)","ko-g56-u11.w.7":"ausleihen, mieten","ko-g56-u11.w.8":"bestellen (Essen)","ko-g56-u11.w.9":"gemeinsam","ko-g56-u11.w.10":"Landschaft, Aussicht","ko-g56-u11.w.11":"Abendrot","ko-g56-u11.s.0":"Wollen wir morgen in den Park gehen?","ko-g56-u11.s.1":"Um wie viel Uhr treffen wir uns?","ko-g56-u11.s.2":"Wollen wir Pizza bestellen?","ko-g56-u11.s.3":"Wollen wir zusammen einen Drachen steigen lassen?","ko-g56-u11.s.4":"Wollen wir die Decke hier ausbreiten?","ko-g56-u11.s.5":"Wir lassen am Han-Fluss Drachen steigen.","ko-g56-u11.s.6":"Das Abendrot ist wirklich schön.","ko-g56-u11.s.7":"Was essen wir heute?","ko-g56-u11.g.title":"Wollen wir …?: -(으)ㄹ까요?","ko-g56-u11.g.x.0":"Um vorzuschlagen, etwas zusammen zu machen, nimm 다 weg und häng ㄹ까요? an: 가다 → 갈까요? (Wollen wir gehen?)","ko-g56-u11.g.x.1":"Nach einem unteren Buchstaben kommt 을까요?: 먹다 → 먹을까요?, 앉다 → 앉을까요?","ko-g56-u11.g.x.2":"Antworte mit 네, 좋아요! oder schlag mit der 요-Form etwas anderes vor: 공원에 가요! (Lass uns in den Park gehen!)","ko-g56-u11.g.0":"Wollen wir am Wochenende picknicken?","ko-g56-u11.g.1":"Was wollen wir essen?","ko-g56-u11.g.2":"Wo treffen wir uns?","ko-g56-u11.g.3":"Wollen wir zusammen Fahrrad fahren?","ko-g56-u11.g.4":"Wollen wir uns hierhin setzen?","ko-g56-u11.g.5":"Wollen wir Brathähnchen bestellen?","ko-g56-u11.g.5.task":"Mach einen Vorschlag daraus: nimm -을까요?","ko-g56-u11.g.6":"Wollen wir am Han-Fluss Drachen steigen lassen?","ko-g56-u11.g.6.task":"Mach einen Vorschlag daraus: nimm -ㄹ까요?","ko-g56-u11.g.7":"Wollen wir heute zusammen in die Bücherei gehen?","ko-g56-u11.g.7.task":"Mach einen Vorschlag daraus: nimm -ㄹ까요?","ko-g56-u11.r.ko":"Ein Picknick am Han-Fluss","ko-g56-u11.r.genre":"Tagebuch","ko-g56-u11.r.p.0":"Sonntag, 3. Oktober. Das Wetter war klar. Meine Familie hat am Han-Fluss ein Picknick gemacht. Mama hat uns Gimbap-Lunchboxen eingepackt.","ko-g56-u11.r.p.1":"Papa fragte: „Wollen wir Fahrräder ausleihen und fahren?“ Wir sind am Fluss entlang geradelt. Der Wind war kühl, darum habe ich mich richtig gut gefühlt.","ko-g56-u11.r.p.2":"Mittags haben wir die Decke ausgebreitet und unsere Lunchboxen gegessen. Mein kleiner Bruder sagte, er möchte auch Hähnchen. Also haben wir uns Hähnchen liefern lassen. Es war erstaunlich, dass Essen sogar an den Han-Fluss geliefert wird.","ko-g56-u11.r.p.3":"Am Abend haben wir Drachen steigen lassen und den Sonnenuntergang angeschaut. Der Himmel wurde rot und war wunderschön. Ich möchte nächstes Wochenende wiederkommen.","ko-g56-u11.r.q.3.o.0":"der rote Himmel beim Sonnenuntergang","ko-g56-u11.r.q.3.o.1":"ein Drachen","ko-g56-u11.r.q.3.o.2":"eine Picknickdecke","ko-g56-u12.title":"Bitte nicht","ko-g56-u12.tip":"In Korea siehst du -지 마세요 auf Schildern: 만지지 마세요 (Nicht berühren), 들어가지 마세요 (Nicht betreten).","ko-g56-u12.w.0":"Lärm machen, quatschen","ko-g56-u12.w.1":"anfassen","ko-g56-u12.w.2":"wegwerfen","ko-g56-u12.w.3":"Müll","ko-g56-u12.w.4":"gefährlich","ko-g56-u12.w.5":"sich Sorgen machen","ko-g56-u12.w.6":"Streich, Unfug","ko-g56-u12.w.7":"Kunstgalerie","ko-g56-u12.w.8":"Kunstwerk","ko-g56-u12.w.9":"Filmen, Fotografieren","ko-g56-u12.w.10":"Essen (und Trinken)","ko-g56-u12.w.11":"sich beeilen","ko-g56-u12.s.0":"Mach in der Bücherei keinen Lärm.","ko-g56-u12.s.1":"Fass das Bild nicht an.","ko-g56-u12.s.2":"Wirf keinen Müll auf die Straße.","ko-g56-u12.s.3":"Mach dir nicht zu viele Sorgen.","ko-g56-u12.s.4":"Lauf nicht auf der Straße. Das ist gefährlich.","ko-g56-u12.s.5":"Hetz nicht auf der Treppe.","ko-g56-u12.s.6":"In der Kunstgalerie bitte nicht fotografieren.","ko-g56-u12.s.7":"Spiel deinem Freund keine Streiche.","ko-g56-u12.g.title":"Bitte nicht: -지 마세요","ko-g56-u12.g.x.0":"Um jemandem höflich zu sagen, dass er etwas nicht tun soll, nimm 다 weg und häng 지 마세요 an: 만지다 → 만지지 마세요 (nicht anfassen).","ko-g56-u12.g.x.1":"Das geht bei jedem Verb gleich: 먹지 마세요, 뛰지 마세요, 걱정하지 마세요.","ko-g56-u12.g.x.2":"Zu einem guten Freund kannst du -지 마 sagen: 울지 마! (Wein nicht!)","ko-g56-u12.g.0":"Bitte fassen Sie das Kunstwerk nicht an.","ko-g56-u12.g.1":"Mach dir keine Sorgen.","ko-g56-u12.g.2":"Bitte im Klassenzimmer keinen Lärm machen.","ko-g56-u12.g.3":"Bitte nicht auf der Straße rennen.","ko-g56-u12.g.4":"Bitte hier nicht essen.","ko-g56-u12.g.5":"Bitte keinen Müll wegwerfen.","ko-g56-u12.g.5.task":"Mach daraus „bitte nicht“: nimm -지 마세요.","ko-g56-u12.g.6":"Bitte in der Kunstgalerie nicht fotografieren.","ko-g56-u12.g.6.task":"Mach daraus „bitte nicht“: nimm -지 마세요.","ko-g56-u12.g.7":"Bitte nicht hetzen.","ko-g56-u12.g.7.task":"Mach daraus „bitte nicht“: nimm -지 마세요.","ko-g56-u13.title":"Vorher und nachher","ko-g56-u13.tip":"Mach mit deiner Familie Gimbap (oder ein einfaches Essen) und sag jeden Schritt auf Koreanisch: 먼저 …, 그다음에 …, 마지막으로 …","ko-g56-u13.w.0":"Zutaten","ko-g56-u13.w.1":"getrockneter Seetang","ko-g56-u13.w.2":"ausbreiten","ko-g56-u13.w.3":"aufrollen","ko-g56-u13.w.4":"in Scheiben schneiden","ko-g56-u13.w.5":"Messer","ko-g56-u13.w.6":"vermischen","ko-g56-u13.w.7":"Sesamöl","ko-g56-u13.w.8":"Schinken","ko-g56-u13.w.9":"eingelegter gelber Rettich","ko-g56-u13.w.10":"zuletzt","ko-g56-u13.w.11":"vorsichtig sein","ko-g56-u13.s.0":"Vor dem Schlafen lese ich ein Buch.","ko-g56-u13.s.1":"Nach dem Aufräumen esse ich einen Snack.","ko-g56-u13.s.2":"Bevor ich zur Schule gehe, frühstücke ich.","ko-g56-u13.s.3":"Nach dem Schwimmen dusche ich.","ko-g56-u13.s.4":"Vor dem Kochen wasche ich die Zutaten.","ko-g56-u13.s.5":"Verteil den Reis auf dem Seetang.","ko-g56-u13.s.6":"Sei vorsichtig, wenn du ein Messer benutzt.","ko-g56-u13.s.7":"Zum Schluss schneidest du das Gimbap in Scheiben.","ko-g56-u13.g.title":"Vorher und nachher: -기 전에 · -(으)ㄴ 후에","ko-g56-u13.g.x.0":"„Bevor man etwas tut“: nimm 다 weg und häng 기 전에 an: 먹다 → 먹기 전에 (vor dem Essen).","ko-g56-u13.g.x.1":"„Nachdem man etwas getan hat“: nimm 다 weg und häng ㄴ 후에 an: 하다 → 한 후에. Nach einem unteren Buchstaben kommt 은 후에: 먹다 → 먹은 후에.","ko-g56-u13.g.x.2":"Bei Nomen häng einfach 전에 oder 후에 an: 수업 전에, 방학 후에.","ko-g56-u13.g.0":"Vor dem Essen wasche ich mir die Hände.","ko-g56-u13.g.1":"Nach den Hausaufgaben spiele ich.","ko-g56-u13.g.2":"Vor dem Schlafengehen putze ich mir die Zähne.","ko-g56-u13.g.3":"Nach dem Essen gehe ich spazieren.","ko-g56-u13.g.4":"Nach der Schule gehe ich zum Taekwondo.","ko-g56-u13.g.5":"Bevor wir Gimbap machen, bereiten wir die Zutaten vor.","ko-g56-u13.g.5.task":"Mach mit -기 전에 einen Satz daraus.","ko-g56-u13.g.6":"Nachdem wir einen Film geschaut haben, essen wir.","ko-g56-u13.g.6.task":"Mach mit -ㄴ 후에 einen Satz daraus.","ko-g56-u13.g.7":"Nach dem Duschen ziehe ich den Schlafanzug an.","ko-g56-u13.g.7.task":"Mach mit -ㄴ 후에 einen Satz daraus.","ko-g56-u13.r.ko":"Wir machen Gimbap","ko-g56-u13.r.genre":"Rezept","ko-g56-u13.r.p.0":"Gimbap ist ein Essen, das Koreaner oft zum Picknick mitnehmen. Heute mache ich mit Mama Gimbap. Bevor wir anfangen, wasche ich mir gründlich die Hände.","ko-g56-u13.r.p.1":"Zuerst bereitest du die Zutaten vor. Du brauchst Seetang, Reis, Ei, Schinken, eingelegten Rettich und Spinat. Gib Salz und Sesamöl in den Reis und misch alles. Mama schneidet Schinken und Ei mit einem Messer in lange Streifen. Messer sind gefährlich, darum sollte ein Erwachsener sie benutzen.","ko-g56-u13.r.p.2":"Verteil den Reis dünn auf dem Seetang. Leg die Füllung darauf und roll alles fest auf. Zum Schluss hat Mama das Gimbap für mich in Scheiben geschnitten. Das Gimbap, das ich gemacht habe, war richtig lecker!","ko-g56-u14.title":"Mit Freunden reden","ko-g56-u14.tip":"In Korea benutzt man 반말 nur, wenn man sich nahesteht und ungefähr gleich alt ist. Wenn du unsicher bist, behalte das 요 — damit liegst du immer richtig.","ko-g56-u14.w.0":"lockere Sprache","ko-g56-u14.w.1":"sich nahestehen (Freunde)","ko-g56-u14.w.2":"jo (lockeres „ja“)","ko-g56-u14.w.3":"nö (lockeres „nein“)","ko-g56-u14.w.4":"danke (locker)","ko-g56-u14.w.5":"sorry (locker)","ko-g56-u14.w.6":"passt schon (locker)","ko-g56-u14.w.7":"was machst du? (locker)","ko-g56-u14.w.8":"lass uns spielen","ko-g56-u14.w.9":"echt (locker)","ko-g56-u14.w.10":"Beziehung","ko-g56-u14.w.11":"gleich alt","ko-g56-u14.s.0":"Sind wir gleich alt?","ko-g56-u14.s.1":"Jo, ich bin auch zehn.","ko-g56-u14.s.2":"Was machst du heute?","ko-g56-u14.s.3":"Lass uns zu mir gehen!","ko-g56-u14.s.4":"Sorry wegen vorhin.","ko-g56-u14.s.5":"Passt schon, mach dir keine Sorgen.","ko-g56-u14.s.6":"Dieses Lied ist echt gut!","ko-g56-u14.s.7":"Mit unserer Lehrerin sprechen wir höflich.","ko-g56-u14.g.title":"Lockere Sprache unter Freunden: 요 weglassen","ko-g56-u14.g.x.0":"Mit guten Freunden und jüngeren Kindern benutzen Koreaner 반말 (lockere Sprache). Meistens lässt du einfach 요 weg: 가요 → 가, 먹어요 → 먹어.","ko-g56-u14.g.x.1":"이에요/예요 werden zu 이야/야: 학생이에요 → 학생이야, 친구예요 → 친구야.","ko-g56-u14.g.x.2":"„Lass uns …“ zu einem Freund heißt -자: 가자! 먹자! 놀자! Und 네 → 응, 아니요 → 아니.","ko-g56-u14.g.x.3":"Benutze bei Erwachsenen, Lehrern und Leuten, die du gerade kennenlernst, immer 요!","ko-g56-u14.g.0":"Was machst du gerade?","ko-g56-u14.g.1":"Ich bin auch zehn.","ko-g56-u14.g.2":"Das ist mein Freund.","ko-g56-u14.g.3":"Lass uns zusammen essen!","ko-g56-u14.g.4":"Sorry, dass ich zu spät bin.","ko-g56-u14.g.5":"Lass uns zusammen spielen!","ko-g56-u14.g.5.task":"Sag es zu einem guten Freund: nimm -자.","ko-g56-u14.g.6":"Dieses Spiel macht echt Spaß!","ko-g56-u14.g.6.task":"Sag es zu einem guten Freund: lass 요 weg und nimm 진짜.","ko-g56-u14.g.7":"Ich bin Schüler.","ko-g56-u14.g.7.task":"Sag es in 반말: 저는 → 나는, 이에요 → 이야.","ko-g56-u15.title":"Wenn …: -(으)ㄹ 때","ko-g56-u15.tip":"Sprich mit -ㄹ 때 über Gefühle: 기쁠 때 노래해요. 슬플 때 엄마를 안아요. Was machst du, wenn dir langweilig ist?","ko-g56-u15.w.0":"schläfrig","ko-g56-u15.w.1":"durstig","ko-g56-u15.w.2":"neugierig","ko-g56-u15.w.3":"verärgert, gekränkt","ko-g56-u15.w.4":"einsam","ko-g56-u15.w.5":"schwer, hart","ko-g56-u15.w.6":"trösten","ko-g56-u15.w.7":"allein","ko-g56-u15.w.8":"Gedanke","ko-g56-u15.w.9":"Erinnerung","ko-g56-u15.w.10":"als ich klein war","ko-g56-u15.w.11":"Karaoke-Raum","ko-g56-u15.s.0":"Wenn mir langweilig ist, male ich.","ko-g56-u15.s.1":"Wenn ich Hunger habe, esse ich einen Apfel.","ko-g56-u15.s.2":"Wenn ich neugierig bin, frage ich die Lehrerin.","ko-g56-u15.s.3":"Wenn mein Freund gekränkt ist, tröste ich ihn.","ko-g56-u15.s.4":"Wenn ich allein bin, lese ich Bücher.","ko-g56-u15.s.5":"Als ich klein war, habe ich auf dem Land gewohnt.","ko-g56-u15.s.6":"Wenn es schwer ist, denke ich an meinen Freund.","ko-g56-u15.s.7":"Wenn ich zum Karaoke gehe, bin ich ganz aufgeregt.","ko-g56-u15.g.title":"Wenn: -(으)ㄹ 때","ko-g56-u15.g.x.0":"Um „wenn (etwas passiert)“ zu sagen, nimm 다 weg und häng ㄹ 때 an: 졸리다 → 졸릴 때 (wenn ich müde bin).","ko-g56-u15.g.x.1":"Nach einem unteren Buchstaben kommt 을 때: 먹다 → 먹을 때, 있다 → 있을 때.","ko-g56-u15.g.x.2":"Für die Vergangenheit nimm 았/었을 때: 어렸을 때 (als ich klein war). Bei Nomen häng einfach 때 an: 방학 때, 점심 때.","ko-g56-u15.g.0":"Wenn ich schläfrig bin, wasche ich mir das Gesicht.","ko-g56-u15.g.1":"Sprich nicht, während du isst.","ko-g56-u15.g.2":"Wenn ich allein bin, höre ich Musik.","ko-g56-u15.g.3":"Wenn du neugierig bist, frag.","ko-g56-u15.g.4":"In den Ferien fahre ich zu Oma.","ko-g56-u15.g.5":"Wenn ich Durst habe, trinke ich Wasser.","ko-g56-u15.g.5.task":"Mach mit -ㄹ 때 einen Satz daraus.","ko-g56-u15.g.6":"Wenn ich gekränkt bin, tröstet mich Mama.","ko-g56-u15.g.6.task":"Mach mit -ㄹ 때 einen Satz daraus.","ko-g56-u15.g.7":"Als ich klein war, habe ich auf dem Land gewohnt.","ko-g56-u15.g.7.task":"Mach mit -았/었을 때 einen Satz daraus.","ko-g56-u16.title":"Eine Geschichte erzählen","ko-g56-u16.tip":"Heungbu und Nolbu ist eines der bekanntesten koreanischen Volksmärchen. Erzähl es deiner Familie mit 먼저, 그다음에, 그런데 und 마지막으로 nach!","ko-g56-u16.w.0":"zuerst","ko-g56-u16.w.1":"danach, dann","ko-g56-u16.w.2":"aber, und dann","ko-g56-u16.w.3":"plötzlich","ko-g56-u16.w.4":"zum Schluss","ko-g56-u16.w.5":"Gier","ko-g56-u16.w.6":"arm","ko-g56-u16.w.7":"reicher Mensch","ko-g56-u16.w.8":"Schwalbe","ko-g56-u16.w.9":"Samen","ko-g56-u16.w.10":"Kürbisflasche","ko-g56-u16.w.11":"Schatz","ko-g56-u16.s.0":"Zuerst mache ich meine Hausaufgaben.","ko-g56-u16.s.1":"Danach spiele ich mit dem Hündchen.","ko-g56-u16.s.2":"Zum Schluss schreibe ich in mein Tagebuch.","ko-g56-u16.s.3":"Wir haben ein Picknick gemacht. Aber wir haben das Essen vergessen.","ko-g56-u16.s.4":"Plötzlich kam ein Hündchen angelaufen.","ko-g56-u16.s.5":"Mir tut der Bauch weh. Darum gehe ich ins Krankenhaus.","ko-g56-u16.s.6":"Nolbu war sehr gierig.","ko-g56-u16.s.7":"Aus der Kürbisflasche kam ein Schatz heraus.","ko-g56-u16.g.title":"Der Reihe nach erzählen: 먼저, 그다음에, 그래서, 그런데","ko-g56-u16.g.x.0":"Setz diese Wörter an den Satzanfang, um der Reihe nach zu erzählen: 먼저 (zuerst) → 그다음에 (danach) → 마지막으로 (zum Schluss).","ko-g56-u16.g.x.1":"그래서 heißt „darum“ (eine Folge): 비가 와요. 그래서 집에 있어요.","ko-g56-u16.g.x.2":"그런데 heißt „aber“ oder „und dann“ (etwas Unerwartetes): 공원에 갔어요. 그런데 문이 닫혀 있었어요.","ko-g56-u16.g.x.3":"갑자기 heißt „plötzlich“: 갑자기 불이 꺼졌어요.","ko-g56-u16.g.0":"Zuerst wasch dir die Hände.","ko-g56-u16.g.1":"Danach iss.","ko-g56-u16.g.2":"Es regnet. Darum nehme ich einen Schirm.","ko-g56-u16.g.3":"Ich bin in den Park gegangen. Aber dann hat es geregnet.","ko-g56-u16.g.4":"Zum Schluss putz dir die Zähne.","ko-g56-u16.g.5":"Ich hatte Hunger. Darum habe ich Brot gegessen.","ko-g56-u16.g.5.task":"Teil es mit 그래서 in zwei Sätze.","ko-g56-u16.g.6":"Ich bin spazieren gegangen. Plötzlich hat es geregnet.","ko-g56-u16.g.6.task":"Füg „plötzlich“ hinzu: nimm 갑자기.","ko-g56-u16.g.7":"Zuerst mache ich meine Hausaufgaben. Danach spiele ich.","ko-g56-u16.g.7.task":"Erzähl es in zwei Schritten: 먼저 … 그다음에 …","ko-g56-u16.r.ko":"Heungbu und Nolbu","ko-g56-u16.r.genre":"Volksmärchen","ko-g56-u16.r.p.0":"Es waren einmal zwei Brüder, Heungbu und Nolbu. Der ältere Bruder Nolbu war reich, aber sehr gierig. Der jüngere Bruder Heungbu war arm, aber gutherzig.","ko-g56-u16.r.p.1":"Eines Frühlingstages sah Heungbu eine Schwalbe mit einem verletzten Bein. Vorsichtig verband er das Bein der Schwalbe. Als der Herbst kam, flog die Schwalbe in den warmen Süden.","ko-g56-u16.r.p.2":"Im nächsten Frühling kam die Schwalbe mit einem Kürbissamen zurück. Als Heungbu ihn pflanzte, wuchsen riesige Kürbisflaschen. Als er eine aufschnitt, quollen Gold und Schätze heraus!","ko-g56-u16.r.p.3":"Als Nolbu die Geschichte hörte, verletzte er absichtlich das Bein einer Schwalbe. Aber aus Nolbus Kürbisflaschen kamen Kobolde und bestraften ihn. Am Ende bereute Nolbu, was er getan hatte, und wurde ein guter Mensch.","ko-g56-u16.r.q.3.o.0":"Gier","ko-g56-u16.r.q.3.o.1":"Güte","ko-g56-u16.r.q.3.o.2":"Schatz"},s={"tier.first.label":"Erste Wörter","tier.first.age":"Auch ohne Lesen","tier.first.desc":"Wort hören, Bild antippen · Lesen nicht nötig","tier.kinder.label":"Hangul","tier.kinder.age":"Hier starten, wenn neu","tier.kinder.desc":"Koreanische Buchstaben und wie sie sich verbinden · Begrüßung, Zahlen, Farben","tier.g12.label":"Erste Sätze","tier.g12.age":"Wenn du Hangul lesen kannst","tier.g12.desc":"Essen, Körper, Schule, Wetter · kurze Sätze","tier.g34.label":"Grammatik-Grundlagen","tier.g34.age":"Wenn du kurze Sätze kannst","tier.g34.desc":"Partikeln, Verbendungen, Vergangenheit und Zukunft · Dialoge","tier.g56.label":"Lesen","tier.g56.age":"Wenn du Sätze bilden kannst","tier.g56.desc":"Können, müssen, höfliche Sprache · kurze Texte"},t={...s,...e,...n,...i,...u,...g};export{t as default};
